insert into bai_hoc (id, mon_id, lop, hoc_ki, chuong, thu_tu, ten, tom_tat, kiem_tra) values
  ('l8_toan_bai_1_don_thuc', 'm_toan', 8, 1, 'Chương 1: Đa thức', 1, 'Bài 1: Đơn thức', 'Đơn thức là biểu thức chỉ gồm tích của một số với các biến (ví dụ 3x²y). Con học thu gọn đơn thức, tìm hệ số, bậc, và cộng trừ các đơn thức đồng dạng (cùng phần biến).', array['Đơn thức 5x²y³ có hệ số bao nhiêu, bậc mấy? → hệ số 5, bậc 5', '2x²y và −3x²y có đồng dạng không? Cộng lại được gì? → có; bằng −x²y']::text[]),
  ('l8_toan_bai_2_da_thuc', 'm_toan', 8, 1, 'Chương 1: Đa thức', 2, 'Bài 2: Đa thức', 'Đa thức là tổng của nhiều đơn thức. Con học thu gọn đa thức (gộp các hạng tử đồng dạng), tìm bậc và tính giá trị của đa thức tại một giá trị cho trước.', array['Thu gọn x² + 2xy − 3x² + xy được gì? → −2x² + 3xy', 'Bậc của đa thức x³y + x² là mấy? → 4']::text[]),
  ('l8_toan_bai_3_phep_cong_va_phep_tru_da_thuc', 'm_toan', 8, 1, 'Chương 1: Đa thức', 3, 'Bài 3: Phép cộng và phép trừ đa thức', 'Cộng, trừ hai đa thức: bỏ dấu ngoặc (có dấu trừ đằng trước thì đổi dấu mọi hạng tử bên trong) rồi gộp các hạng tử đồng dạng.', array['(x² + y) − (x² − y) bằng gì? → 2y', 'Bỏ ngoặc có dấu trừ đằng trước thì hạng tử bên trong thay đổi thế nào? → đổi dấu']::text[]),
  ('l8_toan_luyen_tap_chung_trang_17', 'm_toan', 8, 1, 'Chương 1: Đa thức', 4, 'Luyện tập chung (trang 17)', 'Ôn tổng hợp Bài 1–3: thu gọn đơn thức, đa thức; cộng trừ đa thức.', array['Con làm hết bài luyện tập chưa? Bài nào còn vướng?']::text[]),
  ('l8_toan_bai_4_phep_nhan_da_thuc', 'm_toan', 8, 1, 'Chương 1: Đa thức', 5, 'Bài 4: Phép nhân đa thức', 'Nhân đơn thức với đa thức (nhân vào từng hạng tử) và nhân đa thức với đa thức (mỗi hạng tử của đa thức này nhân với từng hạng tử của đa thức kia rồi cộng lại).', array['2x(x + 3) bằng gì? → 2x² + 6x', '(x + 1)(x + 2) bằng gì? → x² + 3x + 2']::text[]),
  ('l8_toan_bai_5_phep_chia_da_thuc_cho_don_thuc', 'm_toan', 8, 1, 'Chương 1: Đa thức', 6, 'Bài 5: Phép chia đa thức cho đơn thức', 'Chia đơn thức cho đơn thức (chia hệ số, trừ số mũ của từng biến) và chia đa thức cho đơn thức (chia từng hạng tử rồi cộng lại).', array['6x³y : 2x bằng gì? → 3x²y', '(4x² + 2x) : 2x bằng gì? → 2x + 1']::text[]),
  ('l8_toan_luyen_tap_chung_trang_25', 'm_toan', 8, 1, 'Chương 1: Đa thức', 7, 'Luyện tập chung (trang 25)', 'Ôn tổng hợp Bài 4–5: nhân và chia đa thức.', array['Con nhắc lại cách nhân hai đa thức cho bố mẹ nghe.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_1', 'm_toan', 8, 1, 'Chương 1: Đa thức', 8, 'Bài tập cuối chương 1', 'Tổng ôn chương Đa thức: thu gọn, cộng trừ, nhân chia đa thức.', array['Trong chương này con thấy phần nào khó nhất?']::text[]),
  ('l8_toan_bai_6_hieu_hai_binh_phuong_binh_phuong_cua_mot_tong_hay_mot_hieu', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 9, 'Bài 6: Hiệu hai bình phương. Bình phương của một tổng hay một hiệu', 'Ba hằng đẳng thức đầu tiên: a² − b² = (a − b)(a + b); (a + b)² = a² + 2ab + b²; (a − b)² = a² − 2ab + b². Dùng để khai triển, rút gọn và tính nhanh.', array['(x + 3)² khai triển ra gì? → x² + 6x + 9', 'x² − 9 viết thành tích? → (x − 3)(x + 3)', 'Tính nhanh 101² bằng hằng đẳng thức? → (100 + 1)² = 10201']::text[]),
  ('l8_toan_bai_7_lap_phuong_cua_mot_tong_lap_phuong_cua_mot_hieu', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 10, 'Bài 7: Lập phương của một tổng. Lập phương của một hiệu', 'Hai hằng đẳng thức tiếp theo: (a + b)³ = a³ + 3a²b + 3ab² + b³ và (a − b)³ = a³ − 3a²b + 3ab² − b³.', array['(x + 1)³ khai triển ra gì? → x³ + 3x² + 3x + 1', 'Con đọc thuộc công thức lập phương của một hiệu.']::text[]),
  ('l8_toan_bai_8_tong_va_hieu_hai_lap_phuong', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 11, 'Bài 8: Tổng và hiệu hai lập phương', 'Hai hằng đẳng thức cuối: a³ + b³ = (a + b)(a² − ab + b²) và a³ − b³ = (a − b)(a² + ab + b²). Đến đây con đã học đủ 7 hằng đẳng thức đáng nhớ.', array['x³ + 8 phân tích thành tích? → (x + 2)(x² − 2x + 4)', 'Có tất cả bao nhiêu hằng đẳng thức đáng nhớ? Con đọc thuộc cả 7. → 7']::text[]),
  ('l8_toan_luyen_tap_chung_trang_40', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 12, 'Luyện tập chung (trang 40)', 'Ôn 7 hằng đẳng thức: khai triển, viết thành tích, tính nhanh.', array['Bố mẹ đọc một vế, con đọc vế kia của một hằng đẳng thức bất kì.']::text[]),
  ('l8_toan_bai_9_phan_tich_da_thuc_thanh_nhan_tu', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 13, 'Bài 9: Phân tích đa thức thành nhân tử', 'Biến một đa thức thành tích bằng ba cách: đặt nhân tử chung, dùng hằng đẳng thức, nhóm các hạng tử. Kĩ năng này dùng suốt các lớp sau.', array['x² − 4x phân tích ra gì? → x(x − 4)', 'x² − 2x + 1 phân tích ra gì? → (x − 1)²', 'Ba cách phân tích đã học là gì? → đặt nhân tử chung, dùng hằng đẳng thức, nhóm hạng tử']::text[]),
  ('l8_toan_luyen_tap_chung_trang_45', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 14, 'Luyện tập chung (trang 45)', 'Ôn phân tích đa thức thành nhân tử, phối hợp nhiều cách.', array['Con làm được dạng bài nào, còn dạng nào chưa quen?']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_2', 'm_toan', 8, 1, 'Chương 2: Hằng đẳng thức đáng nhớ và ứng dụng', 15, 'Bài tập cuối chương 2', 'Tổng ôn chương Hằng đẳng thức: khai triển, rút gọn, phân tích thành nhân tử.', array['Con tự chấm được bao nhiêu bài đúng trong phần ôn chương?']::text[]),
  ('l8_toan_bai_10_tu_giac', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 16, 'Bài 10: Tứ giác', 'Tứ giác lồi, các yếu tố (đỉnh, cạnh, đường chéo, góc) và tính chất quan trọng nhất: tổng bốn góc của một tứ giác bằng 360°.', array['Tổng các góc trong một tứ giác bằng bao nhiêu độ? → 360°', 'Tứ giác có ba góc 90°, 80°, 100° thì góc còn lại bằng? → 90°']::text[]),
  ('l8_toan_bai_11_hinh_thang_can', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 17, 'Bài 11: Hình thang cân', 'Hình thang là tứ giác có hai cạnh đối song song; hình thang cân có hai góc kề một đáy bằng nhau. Tính chất: hai cạnh bên bằng nhau, hai đường chéo bằng nhau; và dấu hiệu nhận biết.', array['Hai đường chéo của hình thang cân có tính chất gì? → bằng nhau', 'Hình thang có hai đường chéo bằng nhau là hình gì? → hình thang cân']::text[]),
  ('l8_toan_luyen_tap_chung_trang_56', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 18, 'Luyện tập chung (trang 56)', 'Ôn tứ giác và hình thang cân: tính góc, chứng minh hình thang cân.', array['Con vẽ một hình thang cân và chỉ ra hai góc bằng nhau.']::text[]),
  ('l8_toan_bai_12_hinh_binh_hanh', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 19, 'Bài 12: Hình bình hành', 'Tứ giác có các cạnh đối song song. Tính chất: cạnh đối bằng nhau, góc đối bằng nhau, hai đường chéo cắt nhau tại trung điểm mỗi đường; cùng các dấu hiệu nhận biết.', array['Hai đường chéo của hình bình hành có tính chất gì? → cắt nhau tại trung điểm mỗi đường', 'Kể hai dấu hiệu nhận biết hình bình hành.']::text[]),
  ('l8_toan_luyen_tap_chung_trang_62', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 20, 'Luyện tập chung (trang 62)', 'Ôn hình bình hành: dùng tính chất và dấu hiệu để chứng minh.', array['Tứ giác có hai cạnh đối song song và bằng nhau là hình gì? → hình bình hành']::text[]),
  ('l8_toan_bai_13_hinh_chu_nhat', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 21, 'Bài 13: Hình chữ nhật', 'Tứ giác có bốn góc vuông; là hình bình hành có hai đường chéo bằng nhau. Ứng dụng vào tam giác vuông: đường trung tuyến ứng với cạnh huyền bằng nửa cạnh huyền.', array['Hình bình hành có thêm điều kiện gì thì thành hình chữ nhật? → một góc vuông hoặc hai đường chéo bằng nhau', 'Trong tam giác vuông, trung tuyến ứng với cạnh huyền bằng bao nhiêu? → nửa cạnh huyền']::text[]),
  ('l8_toan_bai_14_hinh_thoi_va_hinh_vuong', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 22, 'Bài 14: Hình thoi và hình vuông', 'Hình thoi: bốn cạnh bằng nhau, hai đường chéo vuông góc và là phân giác của các góc. Hình vuông: vừa là hình chữ nhật vừa là hình thoi.', array['Hai đường chéo của hình thoi có gì đặc biệt? → vuông góc với nhau tại trung điểm mỗi đường', 'Hình chữ nhật có hai cạnh kề bằng nhau là hình gì? → hình vuông']::text[]),
  ('l8_toan_luyen_tap_chung_trang_73', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 23, 'Luyện tập chung (trang 73)', 'Ôn hình chữ nhật, hình thoi, hình vuông: nhận biết và chứng minh.', array['Con kể sơ đồ: hình bình hành thêm gì thành hình thoi, thêm gì thành hình vuông?']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_3', 'm_toan', 8, 1, 'Chương 3: Tứ giác', 24, 'Bài tập cuối chương 3', 'Tổng ôn chương Tứ giác: các loại tứ giác đặc biệt, tính chất và dấu hiệu nhận biết.', array['Con vẽ sơ đồ quan hệ giữa các tứ giác đã học.']::text[]),
  ('l8_toan_bai_15_dinh_li_thales_trong_tam_giac', 'm_toan', 8, 1, 'Chương 4: Định lí Thalès', 25, 'Bài 15: Định lí Thalès trong tam giác', 'Tỉ số hai đoạn thẳng, đoạn thẳng tỉ lệ. Định lí Thalès: đường thẳng song song với một cạnh của tam giác định ra trên hai cạnh còn lại những đoạn thẳng tương ứng tỉ lệ; và định lí đảo.', array['Định lí Thalès nói gì? Con vẽ hình minh họa.', 'AB = 6, AC = 9, MN // BC với AM = 2 thì AN bằng? → 3']::text[]),
  ('l8_toan_bai_16_duong_trung_binh_cua_tam_giac', 'm_toan', 8, 1, 'Chương 4: Định lí Thalès', 26, 'Bài 16: Đường trung bình của tam giác', 'Đường trung bình nối trung điểm hai cạnh của tam giác; nó song song với cạnh thứ ba và bằng nửa cạnh ấy.', array['Đường trung bình của tam giác dài bằng bao nhiêu so với cạnh thứ ba? → một nửa', 'BC = 10 cm thì đường trung bình song song với BC dài bao nhiêu? → 5 cm']::text[]),
  ('l8_toan_bai_17_tinh_chat_duong_phan_giac_cua_tam_giac', 'm_toan', 8, 1, 'Chương 4: Định lí Thalès', 27, 'Bài 17: Tính chất đường phân giác của tam giác', 'Đường phân giác của một góc chia cạnh đối diện thành hai đoạn tỉ lệ với hai cạnh kề của góc đó.', array['Phân giác góc A của tam giác ABC chia BC thành hai đoạn tỉ lệ với gì? → AB và AC']::text[]),
  ('l8_toan_luyen_tap_chung_trang_87', 'm_toan', 8, 1, 'Chương 4: Định lí Thalès', 28, 'Luyện tập chung (trang 87)', 'Ôn Thalès, đường trung bình, đường phân giác: tính độ dài, chứng minh song song.', array['Con nói lại ba định lí của chương bằng lời của mình.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_4', 'm_toan', 8, 1, 'Chương 4: Định lí Thalès', 29, 'Bài tập cuối chương 4', 'Tổng ôn chương Định lí Thalès.', array['Chương này con làm được bao nhiêu bài trong phần ôn?']::text[]),
  ('l8_toan_bai_18_thu_thap_va_phan_loai_du_lieu', 'm_toan', 8, 1, 'Chương 5: Dữ liệu và biểu đồ', 30, 'Bài 18: Thu thập và phân loại dữ liệu', 'Cách thu thập dữ liệu (phỏng vấn, quan sát, tra cứu, khảo sát), phân loại dữ liệu định tính và định lượng, kiểm tra tính hợp lí của dữ liệu.', array['Dữ liệu "màu áo yêu thích" là định tính hay định lượng? → định tính', 'Kể hai cách thu thập dữ liệu.']::text[]),
  ('l8_toan_bai_19_bieu_dien_du_lieu_bang_bang_bieu_do', 'm_toan', 8, 1, 'Chương 5: Dữ liệu và biểu đồ', 31, 'Bài 19: Biểu diễn dữ liệu bằng bảng, biểu đồ', 'Chọn dạng biểu đồ phù hợp (cột, cột kép, đoạn thẳng, hình quạt tròn) với từng loại dữ liệu; đọc và vẽ biểu đồ.', array['Muốn thể hiện tỉ lệ phần trăm các phần thì dùng biểu đồ gì? → hình quạt tròn', 'Theo dõi sự thay đổi theo thời gian thì dùng biểu đồ gì? → đoạn thẳng']::text[]),
  ('l8_toan_bai_20_phan_tich_so_lieu_thong_ke_dua_vao_bieu_do', 'm_toan', 8, 1, 'Chương 5: Dữ liệu và biểu đồ', 32, 'Bài 20: Phân tích số liệu thống kê dựa vào biểu đồ', 'Đọc biểu đồ để rút ra nhận xét, so sánh, phát hiện số liệu bất thường hoặc cách vẽ gây hiểu nhầm.', array['Lấy hóa đơn điện nhà mình, con thử nhận xét tháng nào cao nhất và vì sao.']::text[]),
  ('l8_toan_luyen_tap_chung_trang_106', 'm_toan', 8, 1, 'Chương 5: Dữ liệu và biểu đồ', 33, 'Luyện tập chung (trang 106)', 'Ôn thu thập, biểu diễn và phân tích dữ liệu.', array['Con tự làm một bảng thống kê nhỏ (ví dụ giờ ngủ trong tuần) rồi vẽ biểu đồ.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_5', 'm_toan', 8, 1, 'Chương 5: Dữ liệu và biểu đồ', 34, 'Bài tập cuối chương 5', 'Tổng ôn chương Dữ liệu và biểu đồ.', array['Biểu đồ nào con thấy khó đọc nhất? Vì sao?']::text[]),
  ('l8_toan_cong_thuc_lai_kep', 'm_toan', 8, 1, 'Hoạt động thực hành trải nghiệm (học kì 1)', 35, 'Công thức lãi kép', 'Tính tiền gửi ngân hàng theo lãi kép: sau n kì, số tiền A = P(1 + r)ⁿ. Con thấy toán gắn với tiền tiết kiệm thật.', array['Gửi 100 triệu, lãi 6%/năm, sau 2 năm được bao nhiêu? → 112,36 triệu']::text[]),
  ('l8_toan_thuc_hien_tinh_toan_tren_da_thuc_voi_phan_mem_geogebra', 'm_toan', 8, 1, 'Hoạt động thực hành trải nghiệm (học kì 1)', 36, 'Thực hiện tính toán trên đa thức với phần mềm GeoGebra', 'Dùng GeoGebra khai triển, rút gọn, phân tích đa thức để kiểm tra lại kết quả làm tay.', array['Con thử cho GeoGebra khai triển (x + 2)³ rồi so với tay tính.']::text[]),
  ('l8_toan_ve_hinh_don_gian_voi_phan_mem_geogebra', 'm_toan', 8, 1, 'Hoạt động thực hành trải nghiệm (học kì 1)', 37, 'Vẽ hình đơn giản với phần mềm GeoGebra', 'Vẽ điểm, đoạn thẳng, tam giác, tứ giác và đo góc, độ dài trên GeoGebra.', array['Con vẽ một hình bình hành trên GeoGebra và kiểm tra hai đường chéo cắt nhau ở trung điểm.']::text[]),
  ('l8_toan_phan_tich_dac_diem_khi_hau_viet_nam', 'm_toan', 8, 1, 'Hoạt động thực hành trải nghiệm (học kì 1)', 38, 'Phân tích đặc điểm khí hậu Việt Nam', 'Dùng số liệu nhiệt độ, lượng mưa thật để lập bảng, vẽ biểu đồ và nhận xét (liên môn với Địa lí).', array['Tháng nào ở địa phương mình mưa nhiều nhất theo số liệu con tra được?']::text[]),
  ('l8_toan_bai_21_phan_thuc_dai_so', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 39, 'Bài 21: Phân thức đại số', 'Phân thức có dạng A/B với A, B là đa thức và B khác 0. Con học điều kiện xác định (mẫu khác 0), giá trị của phân thức, và hai phân thức bằng nhau khi A·D = B·C.', array['Phân thức 1/(x − 2) xác định khi nào? → x ≠ 2', 'Giá trị của (x + 1)/x tại x = 2 là? → 3/2']::text[]),
  ('l8_toan_bai_22_tinh_chat_co_ban_cua_phan_thuc_dai_so', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 40, 'Bài 22: Tính chất cơ bản của phân thức đại số', 'Nhân hoặc chia cả tử và mẫu với cùng một đa thức khác 0 thì được phân thức bằng nó. Từ đó rút gọn phân thức và quy đồng mẫu thức nhiều phân thức.', array['Rút gọn 2x/(4x²)? → 1/(2x)', 'Muốn quy đồng mẫu hai phân thức thì làm bước gì đầu tiên? → phân tích mẫu thành nhân tử để tìm mẫu chung']::text[]),
  ('l8_toan_luyen_tap_chung_trang_13', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 41, 'Luyện tập chung (trang 13)', 'Ôn khái niệm, rút gọn và quy đồng phân thức.', array['Con rút gọn (x² − 1)/(x + 1) cho bố mẹ xem. → x − 1']::text[]),
  ('l8_toan_bai_23_phep_cong_va_phep_tru_phan_thuc_dai_so', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 42, 'Bài 23: Phép cộng và phép trừ phân thức đại số', 'Cùng mẫu thì cộng, trừ tử và giữ nguyên mẫu; khác mẫu thì quy đồng trước rồi làm như cùng mẫu.', array['1/x + 2/x bằng? → 3/x', '1/x + 1/y bằng? → (x + y)/(xy)']::text[]),
  ('l8_toan_bai_24_phep_nhan_va_phep_chia_phan_thuc_dai_so', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 43, 'Bài 24: Phép nhân và phép chia phân thức đại số', 'Nhân: tử nhân tử, mẫu nhân mẫu. Chia: nhân với phân thức nghịch đảo. Rút gọn kết quả.', array['(x/2) : (x/4) bằng? → 2', 'Nghịch đảo của (x + 1)/x là gì? → x/(x + 1)']::text[]),
  ('l8_toan_luyen_tap_chung_trang_23', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 44, 'Luyện tập chung (trang 23)', 'Ôn bốn phép tính với phân thức và biểu thức phối hợp.', array['Thứ tự thực hiện phép tính với phân thức có giống với phân số không? → giống']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_6', 'm_toan', 8, 2, 'Chương 6: Phân thức đại số', 45, 'Bài tập cuối chương 6', 'Tổng ôn chương Phân thức đại số.', array['Con kể lại các bước rút gọn một biểu thức phân thức.']::text[]),
  ('l8_toan_bai_25_phuong_trinh_bac_nhat_mot_an', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 46, 'Bài 25: Phương trình bậc nhất một ẩn', 'Phương trình dạng ax + b = 0 (a ≠ 0) có nghiệm duy nhất x = −b/a. Giải bằng quy tắc chuyển vế và nhân, chia hai vế; nhiều phương trình đưa được về dạng này.', array['Giải 2x − 6 = 0. → x = 3', 'Giải 3x + 1 = x + 7. → x = 3']::text[]),
  ('l8_toan_bai_26_giai_bai_toan_bang_cach_lap_phuong_trinh', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 47, 'Bài 26: Giải bài toán bằng cách lập phương trình', 'Ba bước: chọn ẩn và đặt điều kiện, lập phương trình từ đề bài, giải rồi đối chiếu điều kiện và trả lời.', array['Tổng hai số là 30, số này hơn số kia 4 — con lập phương trình thế nào? → x + (x + 4) = 30, được 13 và 17']::text[]),
  ('l8_toan_luyen_tap_chung_trang_37', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 48, 'Luyện tập chung (trang 37)', 'Ôn giải phương trình và giải toán bằng cách lập phương trình (chuyển động, năng suất, số học).', array['Con kể một bài toán thực tế đã giải bằng phương trình.']::text[]),
  ('l8_toan_bai_27_khai_niem_ham_so_va_do_thi_cua_ham_so', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 49, 'Bài 27: Khái niệm hàm số và đồ thị của hàm số', 'Hàm số: mỗi giá trị x cho đúng một giá trị y, kí hiệu y = f(x). Mặt phẳng tọa độ Oxy, tọa độ điểm, đồ thị của hàm số.', array['Điểm (2; 3) có hoành độ và tung độ bằng bao nhiêu? → hoành độ 2, tung độ 3', 'f(x) = 2x + 1 thì f(3) bằng? → 7']::text[]),
  ('l8_toan_bai_28_ham_so_bac_nhat_va_do_thi_cua_ham_so_bac_nhat', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 50, 'Bài 28: Hàm số bậc nhất và đồ thị của hàm số bậc nhất', 'Hàm số bậc nhất y = ax + b (a ≠ 0); đồ thị là một đường thẳng, vẽ bằng cách lấy hai điểm (thường là giao với hai trục).', array['Đồ thị y = 2x + 1 cắt trục tung tại điểm nào? → (0; 1)', 'Cần mấy điểm để vẽ đồ thị hàm số bậc nhất? → 2']::text[]),
  ('l8_toan_bai_29_he_so_goc_cua_duong_thang', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 51, 'Bài 29: Hệ số góc của đường thẳng', 'a là hệ số góc: a > 0 đường thẳng đi lên, a < 0 đi xuống. Hai đường thẳng song song khi hệ số góc bằng nhau (và b khác nhau), cắt nhau khi hệ số góc khác nhau.', array['y = 3x − 1 và y = 3x + 5 song song hay cắt nhau? → song song', 'Hệ số góc của y = −2x + 4 là? → −2']::text[]),
  ('l8_toan_luyen_tap_chung_trang_55', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 52, 'Luyện tập chung (trang 55)', 'Ôn hàm số bậc nhất: tính giá trị, vẽ đồ thị, xét vị trí hai đường thẳng.', array['Con vẽ đồ thị y = x − 2 ra giấy.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_7', 'm_toan', 8, 2, 'Chương 7: Phương trình bậc nhất và hàm số bậc nhất', 53, 'Bài tập cuối chương 7', 'Tổng ôn chương Phương trình và hàm số bậc nhất.', array['Con nhắc lại điều kiện để hai đường thẳng song song.']::text[]),
  ('l8_toan_bai_30_ket_qua_co_the_va_ket_qua_thuan_loi', 'm_toan', 8, 2, 'Chương 8: Mở đầu về tính xác suất của biến cố', 54, 'Bài 30: Kết quả có thể và kết quả thuận lợi', 'Liệt kê các kết quả có thể của một hành động (tung xúc xắc: 1 đến 6) và các kết quả thuận lợi cho một biến cố.', array['Tung một con xúc xắc, biến cố "ra số chẵn" có mấy kết quả thuận lợi? → 3 (mặt 2, 4, 6)']::text[]),
  ('l8_toan_bai_31_cach_tinh_xac_suat_cua_bien_co_bang_ti_so', 'm_toan', 8, 2, 'Chương 8: Mở đầu về tính xác suất của biến cố', 55, 'Bài 31: Cách tính xác suất của biến cố bằng tỉ số', 'Khi các kết quả đồng khả năng: xác suất = số kết quả thuận lợi / số kết quả có thể.', array['Xác suất tung xúc xắc được mặt 6 chấm? → 1/6', 'Rút một thẻ từ 10 thẻ đánh số 1–10, xác suất được số chia hết cho 5? → 2/10 = 1/5']::text[]),
  ('l8_toan_bai_32_moi_lien_he_giua_xac_suat_thuc_nghiem_voi_xac_suat_va_ung_dung', 'm_toan', 8, 2, 'Chương 8: Mở đầu về tính xác suất của biến cố', 56, 'Bài 32: Mối liên hệ giữa xác suất thực nghiệm với xác suất và ứng dụng', 'Xác suất thực nghiệm = số lần biến cố xảy ra / số lần thử; thử càng nhiều thì càng gần xác suất lí thuyết, nên dùng để ước lượng xác suất.', array['Tung đồng xu 100 lần được 48 lần sấp — xác suất thực nghiệm của mặt sấp là? → 0,48']::text[]),
  ('l8_toan_luyen_tap_chung_trang_74', 'm_toan', 8, 2, 'Chương 8: Mở đầu về tính xác suất của biến cố', 57, 'Luyện tập chung (trang 74)', 'Ôn tính xác suất bằng tỉ số và xác suất thực nghiệm.', array['Con tung xúc xắc 20 lần, đếm số lần ra mặt 6 và tính xác suất thực nghiệm.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_8', 'm_toan', 8, 2, 'Chương 8: Mở đầu về tính xác suất của biến cố', 58, 'Bài tập cuối chương 8', 'Tổng ôn chương Xác suất.', array['Xác suất luôn nằm trong khoảng nào? → từ 0 đến 1']::text[]),
  ('l8_toan_bai_33_hai_tam_giac_dong_dang', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 59, 'Bài 33: Hai tam giác đồng dạng', 'Hai tam giác đồng dạng khi các góc tương ứng bằng nhau và các cạnh tương ứng tỉ lệ; tỉ số đồng dạng. Đường thẳng song song với một cạnh tạo ra tam giác đồng dạng với tam giác đã cho.', array['Hai tam giác đồng dạng tỉ số 2 thì cạnh của tam giác lớn gấp mấy lần tam giác nhỏ? → 2', 'Kí hiệu đồng dạng viết thế nào? → ∽']::text[]),
  ('l8_toan_bai_34_ba_truong_hop_dong_dang_cua_hai_tam_giac', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 60, 'Bài 34: Ba trường hợp đồng dạng của hai tam giác', 'Cạnh – cạnh – cạnh, cạnh – góc – cạnh, góc – góc. Chỉ cần hai cặp góc bằng nhau là hai tam giác đồng dạng.', array['Hai tam giác có hai cặp góc bằng nhau thì sao? → đồng dạng (trường hợp góc – góc)', 'Kể tên ba trường hợp đồng dạng.']::text[]),
  ('l8_toan_luyen_tap_chung_trang_91', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 61, 'Luyện tập chung (trang 91)', 'Ôn chứng minh tam giác đồng dạng và suy ra tỉ số, độ dài.', array['Con nêu một bài đã dùng trường hợp góc – góc.']::text[]),
  ('l8_toan_bai_35_dinh_li_pythagore_va_ung_dung', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 62, 'Bài 35: Định lí Pythagore và ứng dụng', 'Trong tam giác vuông, bình phương cạnh huyền bằng tổng bình phương hai cạnh góc vuông (a² = b² + c²); định lí đảo dùng để nhận biết tam giác vuông.', array['Tam giác vuông có hai cạnh góc vuông 3 và 4 thì cạnh huyền bằng? → 5', 'Tam giác có ba cạnh 5, 12, 13 có vuông không? → có, vì 5² + 12² = 13²']::text[]),
  ('l8_toan_bai_36_cac_truong_hop_dong_dang_cua_hai_tam_giac_vuong', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 63, 'Bài 36: Các trường hợp đồng dạng của hai tam giác vuông', 'Hai tam giác vuông đồng dạng khi có một góc nhọn bằng nhau, hoặc hai cạnh góc vuông tỉ lệ, hoặc cạnh huyền và một cạnh góc vuông tỉ lệ.', array['Hai tam giác vuông có một góc nhọn bằng nhau thì có đồng dạng không? → có']::text[]),
  ('l8_toan_bai_37_hinh_dong_dang', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 64, 'Bài 37: Hình đồng dạng', 'Hình đồng dạng phối cảnh (phóng to, thu nhỏ từ một tâm) và hình đồng dạng nói chung; nhận ra trong thực tế như ảnh phóng to, bản đồ.', array['Tấm ảnh phóng to gấp đôi có đồng dạng với ảnh gốc không? → có']::text[]),
  ('l8_toan_luyen_tap_chung_trang_108', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 65, 'Luyện tập chung (trang 108)', 'Ôn tam giác đồng dạng, Pythagore, ứng dụng tính khoảng cách.', array['Con giải thích vì sao dùng bóng nắng đo được chiều cao cột cờ.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_9', 'm_toan', 8, 2, 'Chương 9: Tam giác đồng dạng', 66, 'Bài tập cuối chương 9', 'Tổng ôn chương Tam giác đồng dạng.', array['Con nhắc lại định lí Pythagore.']::text[]),
  ('l8_toan_bai_38_hinh_chop_tam_giac_deu', 'm_toan', 8, 2, 'Chương 10: Một số hình khối trong thực tiễn', 67, 'Bài 38: Hình chóp tam giác đều', 'Đáy là tam giác đều, các mặt bên là tam giác cân bằng nhau; trung đoạn. Diện tích xung quanh = ½ · chu vi đáy · trung đoạn; thể tích = ⅓ · diện tích đáy · chiều cao.', array['Hình chóp tam giác đều có mấy mặt? → 4', 'Công thức thể tích hình chóp? → V = ⅓ · S đáy · h']::text[]),
  ('l8_toan_bai_39_hinh_chop_tu_giac_deu', 'm_toan', 8, 2, 'Chương 10: Một số hình khối trong thực tiễn', 68, 'Bài 39: Hình chóp tứ giác đều', 'Đáy là hình vuông, bốn mặt bên là tam giác cân bằng nhau; cùng công thức diện tích xung quanh và thể tích như hình chóp tam giác đều.', array['Hình chóp tứ giác đều có mấy cạnh? → 8', 'Đáy hình vuông cạnh 6, chiều cao 5 thì thể tích bằng? → 60']::text[]),
  ('l8_toan_luyen_tap_chung_trang_121', 'm_toan', 8, 2, 'Chương 10: Một số hình khối trong thực tiễn', 69, 'Luyện tập chung (trang 121)', 'Ôn tính diện tích, thể tích hình chóp đều.', array['Con kể một đồ vật hình chóp ngoài đời.']::text[]),
  ('l8_toan_bai_tap_cuoi_chuong_10', 'm_toan', 8, 2, 'Chương 10: Một số hình khối trong thực tiễn', 70, 'Bài tập cuối chương 10', 'Tổng ôn chương Hình khối.', array['Kim tự tháp Ai Cập là hình chóp gì? → hình chóp tứ giác đều']::text[]),
  ('l8_toan_mot_vai_ung_dung_cua_ham_so_bac_nhat_trong_tai_chinh', 'm_toan', 8, 2, 'Hoạt động thực hành trải nghiệm (học kì 2)', 71, 'Một vài ứng dụng của hàm số bậc nhất trong tài chính', 'Tiền cước, tiền lương theo giờ, lãi đơn… đều là hàm số bậc nhất; lập công thức, vẽ đồ thị để so sánh các phương án.', array['Gói cước 50 nghìn/tháng + 1 nghìn/GB — con viết công thức tiền phải trả theo số GB. → y = 50 + x (nghìn đồng)']::text[]),
  ('l8_toan_ung_dung_dinh_li_thales_dinh_li_pythagore_va_tam_giac_dong_dang_de_do_chieu_cao', 'm_toan', 8, 2, 'Hoạt động thực hành trải nghiệm (học kì 2)', 72, 'Ứng dụng định lí Thalès, định lí Pythagore và tam giác đồng dạng để đo chiều cao, khoảng cách', 'Đo chiều cao cây, cột cờ bằng bóng nắng hoặc cọc và tam giác đồng dạng; đo khoảng cách không tới được.', array['Con thử đo chiều cao một cái cây gần nhà bằng bóng nắng.']::text[]),
  ('l8_toan_thuc_hanh_tinh_toan_tren_phan_thuc_dai_so_va_ve_do_thi_ham_so_voi_phan_mem_geoge', 'm_toan', 8, 2, 'Hoạt động thực hành trải nghiệm (học kì 2)', 73, 'Thực hành tính toán trên phân thức đại số và vẽ đồ thị hàm số với phần mềm GeoGebra', 'Dùng GeoGebra rút gọn phân thức và vẽ đồ thị hàm số bậc nhất, kiểm tra kết quả làm tay.', array['Con vẽ y = 2x − 1 trên GeoGebra và chỉ giao điểm với trục tung.']::text[]),
  ('l8_toan_mo_ta_thi_nghiem_ngau_nhien_voi_phan_mem_excel', 'm_toan', 8, 2, 'Hoạt động thực hành trải nghiệm (học kì 2)', 74, 'Mô tả thí nghiệm ngẫu nhiên với phần mềm Excel', 'Dùng hàm RANDBETWEEN mô phỏng tung xúc xắc nhiều lần rồi tính xác suất thực nghiệm.', array['Mô phỏng 1000 lần thì tỉ lệ ra mặt 6 gần con số nào? → khoảng 1/6 ≈ 0,167']::text[]),
  ('l8_toan_bai_tap_on_tap_cuoi_nam', 'm_toan', 8, 2, 'Hoạt động thực hành trải nghiệm (học kì 2)', 75, 'Bài tập ôn tập cuối năm', 'Ôn toàn bộ Toán 8: đa thức, hằng đẳng thức, tứ giác, Thalès, thống kê, phân thức, phương trình, hàm số, xác suất, tam giác đồng dạng, hình chóp.', array['Con liệt kê các chương đã học và tự đánh giá mỗi chương nắm được bao nhiêu phần trăm.']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_9', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 1, 'Tri thức ngữ văn trang 9', 'Học về truyện lịch sử: truyện lấy đề tài từ sự kiện, nhân vật có thật trong quá khứ; bối cảnh, cốt truyện, nhân vật và ngôn ngữ mang dấu ấn thời đại.', array['Truyện lịch sử khác truyện thường ở chỗ nào? → dựa trên sự kiện, nhân vật lịch sử có thật']::text[]),
  ('l8_van_la_co_theu_sau_chu_vang', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 2, 'Lá cờ thêu sáu chữ vàng', 'Trích tiểu thuyết của Nguyễn Huy Tưởng về Trần Quốc Toản: chàng thiếu niên bóp nát quả cam vì không được dự hội nghị Bình Than, quyết chiêu binh đánh giặc Nguyên dưới lá cờ "Phá cường địch, báo hoàng ân".', array['Sáu chữ vàng trên lá cờ là gì? → Phá cường địch, báo hoàng ân', 'Vì sao Trần Quốc Toản bóp nát quả cam?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_16', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 3, 'Thực hành tiếng Việt trang 16', 'Biệt ngữ xã hội: từ ngữ chỉ dùng trong một nhóm người (học sinh, người buôn bán…). Nhận biết và biết dùng đúng chỗ, tránh lạm dụng trong văn viết.', array['Con kể vài biệt ngữ của học sinh bây giờ. Dùng trong bài văn có được không? → không nên, chỉ dùng trong nhóm hoặc để tả nhân vật']::text[]),
  ('l8_van_quang_trung_dai_pha_quan_thanh', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 4, 'Quang Trung đại phá quân Thanh', 'Trích "Hoàng Lê nhất thống chí" (Ngô gia văn phái): Nguyễn Huệ lên ngôi, hành quân thần tốc, đại phá 29 vạn quân Thanh Tết Kỷ Dậu 1789. Hình ảnh vua anh hùng đối lập với Lê Chiêu Thống hèn nhát.', array['Quang Trung đánh tan quân Thanh vào dịp nào? → Tết Kỷ Dậu 1789', 'Qua đoạn trích con thấy Quang Trung là người thế nào?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_24', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 5, 'Thực hành tiếng Việt trang 24', 'Từ ngữ địa phương: từ chỉ dùng ở một vùng (má, tía, bắp, mô, tê…). Tác dụng trong văn chương và lưu ý khi dùng trong giao tiếp chung.', array['"Má", "u", "bầm" đều chỉ ai? Mỗi từ ở vùng nào? → mẹ; Nam Bộ, Bắc Bộ, trung du Bắc Bộ']::text[]),
  ('l8_van_ta_di_toi', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 6, 'Ta đi tới', 'Thơ Tố Hữu (1954): niềm vui chiến thắng và hành trình "ta đi tới" khắp mọi miền đất nước sau chiến thắng Điện Biên Phủ, niềm tin thống nhất.', array['Bài thơ viết trong hoàn cảnh nào? → sau chiến thắng Điện Biên Phủ 1954', 'Con nhớ câu thơ nào trong bài?']::text[]),
  ('l8_van_viet_bai_van_ke_lai_mot_chuyen_di_tham_quan_mot_di_tich_lich_su_van_hoa', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 7, 'Viết bài văn kể lại một chuyến đi (tham quan một di tích lịch sử, văn hóa)', 'Bài văn tự sự có mở – thân – kết, kể theo trình tự, kết hợp miêu tả và biểu cảm, nêu ý nghĩa chuyến đi.', array['Con định kể chuyến đi nào? Dàn ý ba phần có gì?']::text[]),
  ('l8_van_trinh_bay_bai_gioi_thieu_ngan_ve_mot_cuon_sach_cuon_truyen_lich_su', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 8, 'Trình bày bài giới thiệu ngắn về một cuốn sách (cuốn truyện lịch sử)', 'Nói trước lớp: tên sách, tác giả, nội dung chính, điều thích nhất; nói rõ ràng, có mở đầu và kết thúc.', array['Con chọn cuốn nào? Nói thử cho bố mẹ nghe trong một phút.']::text[]),
  ('l8_van_cung_co_mo_rong_trang_34', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 9, 'Củng cố, mở rộng trang 34', 'Ôn lại đặc điểm truyện lịch sử qua hai văn bản đã học; gợi ý đọc thêm.', array['Hai văn bản truyện lịch sử đã học có điểm gì giống nhau?']::text[]),
  ('l8_van_thuc_hanh_doc_minh_su', 'm_van', 8, 1, 'Bài 1: Câu chuyện của lịch sử', 10, 'Thực hành đọc: Minh sư', 'Trích tiểu thuyết của Thái Bá Lợi về Nguyễn Hoàng — người mở cõi phương Nam; suy ngẫm rằng "người thầy" có thể là chính kẻ đối nghịch với mình.', array['Nhân vật chính của đoạn trích là ai? → Nguyễn Hoàng']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_39', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 11, 'Tri thức ngữ văn trang 39', 'Thơ Đường luật: thất ngôn bát cú và tứ tuyệt; luật bằng trắc, niêm, vần, đối; bố cục đề – thực – luận – kết.', array['Bài thất ngôn bát cú có mấy câu, mỗi câu mấy chữ? → 8 câu, 7 chữ']::text[]),
  ('l8_van_thu_dieu', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 12, 'Thu điếu', 'Nguyễn Khuyến — "Câu cá mùa thu": bức tranh thu làng quê Bắc Bộ trong trẻo, tĩnh lặng (ao thu, thuyền câu, lá vàng, trời xanh) và tâm sự u hoài của nhà thơ.', array['Bài thơ tả cảnh gì, ở đâu? → mùa thu ở ao làng quê Bắc Bộ', 'Câu cuối "Cá đâu đớp động dưới chân bèo" gợi cảm giác gì?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_42', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 13, 'Thực hành tiếng Việt trang 42', 'Từ tượng hình (gợi dáng vẻ: lom khom, lấp lánh) và từ tượng thanh (gợi âm thanh: róc rách, ầm ầm); tác dụng gợi hình, gợi cảm trong thơ văn.', array['"Lộp độp" và "lênh khênh" — từ nào tượng thanh, từ nào tượng hình? → lộp độp: tượng thanh; lênh khênh: tượng hình']::text[]),
  ('l8_van_thien_truong_van_vong', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 14, 'Thiên Trường vãn vọng', 'Trần Nhân Tông — "Buổi chiều đứng ở phủ Thiên Trường trông ra": cảnh chiều quê thanh bình với mục đồng, cò trắng; tâm hồn gắn bó với dân của vị vua.', array['Tác giả bài thơ là ai? → vua Trần Nhân Tông', 'Cảnh trong bài có những hình ảnh gì?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_45', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 15, 'Thực hành tiếng Việt trang 45', 'Biện pháp tu từ đảo ngữ (đổi trật tự từ để nhấn mạnh) và câu hỏi tu từ (hỏi để bộc lộ cảm xúc, không cần trả lời).', array['Câu hỏi tu từ có cần trả lời không? → không, dùng để nhấn mạnh hoặc bộc lộ cảm xúc']::text[]),
  ('l8_van_ca_hue_tren_song_huong', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 16, 'Ca Huế trên sông Hương', 'Văn bản thuyết minh (Hà Ánh Minh) về sinh hoạt ca Huế: nguồn gốc từ nhạc dân gian và nhạc cung đình, các làn điệu, nhạc cụ và không gian đêm sông Hương.', array['Ca Huế bắt nguồn từ đâu? → nhạc dân gian và nhạc cung đình']::text[]),
  ('l8_van_viet_bai_van_phan_tich_mot_tac_pham_van_hoc_bai_tho_that_ngon_bat_cu_hoac_tu_tuy', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 17, 'Viết bài văn phân tích một tác phẩm văn học (bài thơ thất ngôn bát cú hoặc tứ tuyệt Đường luật)', 'Phân tích nội dung (đề tài, cảm xúc) và nghệ thuật (thể thơ, hình ảnh, biện pháp tu từ) của một bài thơ Đường luật theo bố cục ba phần.', array['Con chọn phân tích bài thơ nào? Ý chính mỗi phần là gì?']::text[]),
  ('l8_van_trinh_bay_y_kien_ve_mot_van_de_xa_hoi_mot_san_pham_van_hoa_truyen_thong_trong_cu', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 18, 'Trình bày ý kiến về một vấn đề xã hội (một sản phẩm văn hóa truyền thống trong cuộc sống hiện tại)', 'Nói – nghe: chọn một sản phẩm (áo dài, tranh Đông Hồ, ca Huế…), nêu ý kiến về chỗ đứng của nó hôm nay với lí lẽ, dẫn chứng.', array['Con chọn sản phẩm văn hóa nào? Vì sao?']::text[]),
  ('l8_van_cung_co_mo_rong_trang_55', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 19, 'Củng cố, mở rộng trang 55', 'Ôn đặc điểm thơ Đường luật qua các bài đã học; đọc thêm.', array['Hai bài thơ Đường luật đã học có gì khác nhau về cảm xúc?']::text[]),
  ('l8_van_thuc_hanh_doc_qua_deo_ngang', 'm_van', 8, 1, 'Bài 2: Vẻ đẹp cổ điển', 20, 'Thực hành đọc: Qua Đèo Ngang', 'Bà Huyện Thanh Quan: cảnh đèo hoang sơ lúc chiều tà và nỗi nhớ nước thương nhà, cô đơn "một mảnh tình riêng ta với ta".', array['Câu kết của bài thơ là gì? → Một mảnh tình riêng, ta với ta']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_58', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 21, 'Tri thức ngữ văn trang 58', 'Văn nghị luận: luận đề, luận điểm, lí lẽ, bằng chứng; các thể văn nghị luận trung đại như hịch, chiếu, cáo.', array['Luận điểm là gì? → ý kiến chính người viết nêu ra để làm rõ luận đề']::text[]),
  ('l8_van_hich_tuong_si', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 22, 'Hịch tướng sĩ', 'Trần Quốc Tuấn viết trước kháng chiến chống Nguyên lần hai: vạch tội giặc, bày tỏ lòng căm thù, phê phán thái độ thờ ơ của tướng sĩ và kêu gọi học "Binh thư yếu lược".', array['Ai viết Hịch tướng sĩ, nhằm mục đích gì? → Trần Quốc Tuấn, khích lệ tướng sĩ đánh giặc', 'Câu nào thể hiện lòng căm thù giặc? → "Ta thường tới bữa quên ăn, nửa đêm vỗ gối…"']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_64', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 23, 'Thực hành tiếng Việt trang 64', 'Đoạn văn diễn dịch (câu chủ đề ở đầu đoạn) và đoạn văn quy nạp (câu chủ đề ở cuối đoạn).', array['Đoạn diễn dịch có câu chủ đề ở đâu? → đầu đoạn']::text[]),
  ('l8_van_tinh_than_yeu_nuoc_cua_nhan_dan_ta', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 24, 'Tinh thần yêu nước của nhân dân ta', 'Hồ Chí Minh (1951): dân ta có một lòng nồng nàn yêu nước, chứng minh qua lịch sử và hiện tại; nhiệm vụ là làm cho tinh thần ấy được thực hành vào công việc kháng chiến.', array['Tác giả so sánh lòng yêu nước với hình ảnh gì? → làn sóng mạnh mẽ; các thứ của quý']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_68', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 25, 'Thực hành tiếng Việt trang 68', 'Đoạn văn song song (các câu ngang hàng, không có câu chủ đề) và đoạn văn phối hợp (câu chủ đề ở cả đầu và cuối).', array['Đoạn phối hợp có câu chủ đề ở đâu? → cả đầu và cuối đoạn']::text[]),
  ('l8_van_nam_quoc_son_ha', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 26, 'Nam quốc sơn hà', 'Bài thơ thần thời Lý, được coi là bản tuyên ngôn độc lập đầu tiên: nước Nam là của vua Nam, sách trời đã định, giặc xâm phạm ắt chuốc bại.', array['Vì sao bài thơ được coi là bản tuyên ngôn độc lập đầu tiên?', 'Con đọc thuộc bài thơ.']::text[]),
  ('l8_van_viet_bai_van_nghi_luan_ve_mot_van_de_doi_song_con_nguoi_trong_moi_quan_he_voi_co', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 27, 'Viết bài văn nghị luận về một vấn đề đời sống (con người trong mối quan hệ với cộng đồng, đất nước)', 'Nêu vấn đề, trình bày ý kiến với lí lẽ và bằng chứng, phản bác ý kiến trái chiều, kết luận.', array['Con chọn vấn đề gì? Bằng chứng con định dùng là gì?']::text[]),
  ('l8_van_thao_luan_ve_mot_van_de_trong_doi_song_phu_hop_voi_lua_tuoi_y_thuc_trach_nhiem_v', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 28, 'Thảo luận về một vấn đề trong đời sống phù hợp với lứa tuổi (ý thức trách nhiệm với cộng đồng của học sinh)', 'Nói – nghe: trình bày ý kiến, lắng nghe bạn, phản hồi lịch sự và có lí lẽ.', array['Theo con, học sinh có trách nhiệm gì với cộng đồng?']::text[]),
  ('l8_van_cung_co_mo_rong_trang_77', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 29, 'Củng cố, mở rộng trang 77', 'Ôn đặc điểm văn nghị luận qua ba văn bản đã học.', array['Ba văn bản đã học cùng nói về điều gì? → lòng yêu nước']::text[]),
  ('l8_van_thuc_hanh_doc_chieu_doi_do', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 30, 'Thực hành đọc: Chiếu dời đô', 'Lý Công Uẩn (1010) nêu lí do dời đô từ Hoa Lư về Đại La (Thăng Long): thế đất rồng cuộn hổ ngồi, thuận lợi muôn đời.', array['Dời đô từ đâu về đâu? → Hoa Lư về Đại La (Thăng Long)']::text[]),
  ('l8_van_doc_mo_rong_trang_79', 'm_van', 8, 1, 'Bài 3: Lời sông núi', 31, 'Đọc mở rộng trang 79', 'Tự chọn đọc truyện lịch sử, thơ Đường luật, văn nghị luận và ghi nhật kí đọc.', array['Con đang đọc cuốn gì? Kể một điều thú vị.']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_81', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 32, 'Tri thức ngữ văn trang 81', 'Thơ trào phúng dùng tiếng cười để phê phán, châm biếm; các giọng điệu hài hước, mỉa mai, đả kích; nghĩa của từ Hán Việt.', array['Thơ trào phúng nhằm mục đích gì? → phê phán, châm biếm bằng tiếng cười']::text[]),
  ('l8_van_le_xuong_danh_khoa_dinh_dau', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 33, 'Lễ xướng danh khoa Đinh Dậu', 'Trần Tế Xương (Tú Xương): cảnh trường thi Nam Định 1897 nhốn nháo, sĩ tử "lôi thôi", quan trường "ậm ọe", có mặt quan Tây và "mụ đầm" — nỗi nhục mất nước.', array['Bài thơ tả cảnh gì? → lễ xướng danh kì thi Hương năm 1897', 'Tác giả chua xót về điều gì?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_84', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 34, 'Thực hành tiếng Việt trang 84', 'Nghĩa của một số từ, thành ngữ Hán Việt (sĩ tử, nhân tài, tang thương…); cách tra và dùng đúng.', array['"Thiên" trong "thiên tử" và "thiên niên kỉ" nghĩa khác nhau thế nào? → trời / nghìn']::text[]),
  ('l8_van_lai_tan', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 35, 'Lai Tân', 'Hồ Chí Minh ("Nhật kí trong tù"): ba câu kể ban trưởng đánh bạc, cảnh trưởng ăn hối lộ, huyện trưởng hút thuốc phiện — câu kết "Trời đất Lai Tân vẫn thái bình" mỉa mai sâu cay.', array['Câu cuối bài thơ có ý mỉa mai gì?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_86', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 36, 'Thực hành tiếng Việt trang 86', 'Sắc thái nghĩa của từ ngữ (trang trọng, thân mật, khen, chê…) và việc lựa chọn từ cho phù hợp hoàn cảnh.', array['"Chết", "hi sinh", "toi" — sắc thái khác nhau ra sao? → trung tính / trang trọng, kính trọng / suồng sã, coi thường']::text[]),
  ('l8_van_mot_so_giong_dieu_cua_tieng_cuoi_trong_tho_trao_phung', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 37, 'Một số giọng điệu của tiếng cười trong thơ trào phúng', 'Văn bản nghị luận (Trần Thị Hoa Lê): hài hước, mỉa mai – châm biếm, đả kích là các giọng điệu chính, minh họa bằng thơ Tú Xương, Nguyễn Khuyến.', array['Kể ba giọng điệu của tiếng cười trào phúng. → hài hước; mỉa mai – châm biếm; đả kích']::text[]),
  ('l8_van_viet_bai_van_phan_tich_mot_tac_pham_van_hoc_tho_trao_phung', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 38, 'Viết bài văn phân tích một tác phẩm văn học (thơ trào phúng)', 'Phân tích đối tượng bị cười, giọng điệu, nghệ thuật gây cười và thái độ của tác giả.', array['Con phân tích bài thơ nào? Đối tượng bị cười là ai?']::text[]),
  ('l8_van_trinh_bay_y_kien_ve_mot_van_de_xa_hoi_y_nghia_cua_tieng_cuoi_trong_doi_song', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 39, 'Trình bày ý kiến về một vấn đề xã hội (ý nghĩa của tiếng cười trong đời sống)', 'Nói – nghe: tiếng cười giúp gì cho cuộc sống, khi nào cười là không phù hợp.', array['Theo con, tiếng cười có ý nghĩa gì?']::text[]),
  ('l8_van_cung_co_mo_rong_trang_97', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 40, 'Củng cố, mở rộng trang 97', 'Ôn thơ trào phúng qua các bài đã học.', array['Hai bài thơ trào phúng đã học cười ai, cười cái gì?']::text[]),
  ('l8_van_thuc_hanh_doc_vinh_cay_vong', 'm_van', 8, 1, 'Bài 4: Tiếng cười trào phúng trong thơ', 41, 'Thực hành đọc: Vịnh cây vông', 'Nguyễn Công Trứ mượn cây vông (to mà rỗng, gỗ không dùng được) để châm biếm kẻ có danh mà bất tài.', array['Cây vông trong bài tượng trưng cho hạng người nào? → kẻ có danh mà bất tài']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_100', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 42, 'Tri thức ngữ văn trang 100', 'Hài kịch (xung đột, nhân vật, hành động, thủ pháp gây cười) và truyện cười dân gian (ngắn, kết bất ngờ); nghĩa tường minh và nghĩa hàm ẩn.', array['Truyện cười thường gây cười bằng cách nào? → tình huống bất ngờ, phóng đại, nói ngược']::text[]),
  ('l8_van_truong_gia_hoc_lam_sang', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 43, 'Trưởng giả học làm sang', 'Trích hài kịch của Mô-li-e (Pháp): ông Giuốc-đanh giàu mà ngu ngốc, đòi học làm quý tộc, bị thợ may và bọn thợ phụ lợi dụng bằng những lời tâng bốc "ông lớn, cụ lớn, đức ông".', array['Ông Giuốc-đanh bị lừa như thế nào?', 'Tác giả Mô-li-e là người nước nào? → Pháp']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_107', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 44, 'Thực hành tiếng Việt trang 107', 'Câu hỏi tu từ: hỏi không để lấy thông tin mà để khẳng định, phủ định hay bộc lộ cảm xúc; tác dụng trong văn bản.', array['Con đặt một câu hỏi tu từ.']::text[]),
  ('l8_van_chum_truyen_cuoi_dan_gian_viet_nam', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 45, 'Chùm truyện cười dân gian Việt Nam', '"Lợn cưới, áo mới", "Treo biển", "Nói dóc gặp nhau": cười thói khoe khoang, thiếu chủ kiến, nói khoác.', array['Truyện "Treo biển" cười thói gì? → thiếu chủ kiến, ai nói gì cũng nghe theo']::text[]),
  ('l8_van_chum_ca_dao_trao_phung', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 46, 'Chùm ca dao trào phúng', 'Ca dao châm biếm thầy bói, thầy cúng, kẻ lười biếng… bằng lối nói ngược, phóng đại.', array['Bài ca dao "Số cô chẳng giàu thì nghèo…" cười ai? → thầy bói']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_113', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 47, 'Thực hành tiếng Việt trang 113', 'Nghĩa tường minh (nói thẳng) và nghĩa hàm ẩn (ý ngầm phải suy ra); nghĩa hàm ẩn trong truyện cười, tục ngữ.', array['"Trời nóng quá" nói với người đang ngồi cạnh quạt có hàm ẩn gì? → nhờ bật quạt']::text[]),
  ('l8_van_viet_bai_van_nghi_luan_ve_mot_van_de_doi_song_mot_thoi_xau_cua_con_nguoi_trong_x', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 48, 'Viết bài văn nghị luận về một vấn đề đời sống (một thói xấu của con người trong xã hội hiện đại)', 'Chọn một thói xấu (nói dối, lười biếng, nghiện điện thoại…), nêu biểu hiện, tác hại, cách khắc phục với lí lẽ, bằng chứng.', array['Con chọn thói xấu nào? Tác hại lớn nhất là gì?']::text[]),
  ('l8_van_trinh_bay_y_kien_ve_mot_van_de_xa_hoi_mot_thoi_xau_cua_con_nguoi_trong_xa_hoi_hi', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 49, 'Trình bày ý kiến về một vấn đề xã hội (một thói xấu của con người trong xã hội hiện đại)', 'Nói – nghe: trình bày ý kiến về một thói xấu, lắng nghe và phản hồi.', array['Con nói thử một phút về thói xấu đã chọn.']::text[]),
  ('l8_van_cung_co_mo_rong_trang_120', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 50, 'Củng cố, mở rộng trang 120', 'Ôn hài kịch và truyện cười.', array['Tiếng cười trong hài kịch và trong truyện cười dân gian khác nhau ở đâu?']::text[]),
  ('l8_van_thuc_hanh_doc_gia_khong_co_ruoi', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 51, 'Thực hành đọc: Giá không có ruồi', 'Truyện cười của A-dít Nê-xin (Thổ Nhĩ Kì): nhà văn đổ lỗi cho con ruồi để trì hoãn viết — châm biếm thói lười biếng, hay viện cớ.', array['Nhân vật viện cớ gì để không viết? → con ruồi']::text[]),
  ('l8_van_doc_mo_rong_trang_123', 'm_van', 8, 1, 'Bài 5: Những câu chuyện hài', 52, 'Đọc mở rộng trang 123', 'Tự chọn đọc thơ trào phúng, hài kịch, truyện cười và ghi nhật kí đọc.', array['Con đọc thêm được truyện cười nào? Kể lại cho cả nhà.']::text[]),
  ('l8_van_on_tap_hoc_ki_i', 'm_van', 8, 1, 'Ôn tập học kì I', 53, 'Ôn tập học kì I', 'Hệ thống các thể loại đã học (truyện lịch sử, thơ Đường luật, văn nghị luận, thơ trào phúng, hài kịch – truyện cười), kiến thức tiếng Việt và các kiểu bài viết.', array['Con kể tên năm thể loại đã học trong học kì I.']::text[]),
  ('l8_van_a_on_tap_kien_thuc_on_tap_hoc_ki_1', 'm_van', 8, 1, 'Ôn tập học kì I', 54, 'A. Ôn tập kiến thức (Ôn tập học kì 1)', 'Bảng tổng kết: văn bản – thể loại – đặc điểm; tiếng Việt: biệt ngữ, từ địa phương, từ tượng hình – tượng thanh, đoạn văn, từ Hán Việt, nghĩa hàm ẩn.', array['Con nhắc lại một kiến thức tiếng Việt học kì này và cho ví dụ.']::text[]),
  ('l8_van_soan_bai_phieu_hoc_tap_so_1', 'm_van', 8, 1, 'Ôn tập học kì I', 55, 'Soạn bài Phiếu học tập số 1', 'Luyện đọc hiểu một văn bản mới và viết theo đề tương tự đề kiểm tra học kì.', array['Con làm phiếu này mất bao lâu? Câu nào khó nhất?']::text[]),
  ('l8_van_soan_bai_phieu_hoc_tap_so_2', 'm_van', 8, 1, 'Ôn tập học kì I', 56, 'Soạn bài Phiếu học tập số 2', 'Luyện đọc hiểu và viết, đề số 2, theo cấu trúc đề kiểm tra học kì.', array['Con tự chấm được bao nhiêu điểm phần đọc hiểu?']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_5', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 57, 'Tri thức ngữ văn trang 5', 'Truyện: cốt truyện đa tuyến, nhân vật, người kể chuyện, ngôi kể; trợ từ và thán từ.', array['Cốt truyện đa tuyến là gì? → có nhiều tuyến truyện đan xen']::text[]),
  ('l8_van_mat_soi', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 58, 'Mắt sói', 'Trích tiểu thuyết của Đa-ni-en Pen-nắc: cậu bé Phi Châu và con Sói Lam nhìn vào mắt nhau, thấy lại quá khứ đau thương của nhau — tình bạn và lòng trắc ẩn giữa người và loài vật.', array['Hai nhân vật chính là ai? → Phi Châu và Sói Lam', 'Vì sao Sói Lam chỉ còn một mắt?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_14', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 59, 'Thực hành tiếng Việt trang 14', 'Trợ từ: từ đi kèm để nhấn mạnh hoặc bày tỏ thái độ (những, có, chính, ngay, đến, cả…).', array['Trong "Nó ăn những ba bát cơm", từ nào là trợ từ? → những']::text[]),
  ('l8_van_lang_le_sa_pa', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 60, 'Lặng lẽ Sa Pa', 'Nguyễn Thành Long: anh thanh niên làm khí tượng một mình trên đỉnh Yên Sơn, yêu nghề, khiêm tốn, hiếu khách — vẻ đẹp của người lao động thầm lặng.', array['Anh thanh niên làm công việc gì? → đo gió, mưa, nắng… (khí tượng kiêm vật lí địa cầu)', 'Điều gì ở anh thanh niên khiến con thích?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_23', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 61, 'Thực hành tiếng Việt trang 23', 'Thán từ: từ bộc lộ cảm xúc (ôi, chao, a…) hoặc dùng để gọi đáp (này, vâng, dạ, ơi).', array['"Ôi" và "vâng" — từ nào bộc lộ cảm xúc, từ nào gọi đáp? → ôi: cảm xúc; vâng: gọi đáp']::text[]),
  ('l8_van_bep_lua', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 62, 'Bếp lửa', 'Bằng Việt: kỉ niệm tuổi thơ bên bà và bếp lửa những năm đói khổ, chiến tranh; lòng biết ơn bà và tình yêu quê hương, đất nước.', array['Bài thơ nói về ai? → người bà', 'Hình ảnh bếp lửa tượng trưng cho điều gì? → tình bà cháu, sự ấm áp, sức sống bền bỉ']::text[]),
  ('l8_van_viet_bai_van_phan_tich_mot_tac_pham_truyen', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 63, 'Viết bài văn phân tích một tác phẩm (truyện)', 'Phân tích cốt truyện, nhân vật, chủ đề và nghệ thuật kể chuyện của một truyện đã học hoặc tự chọn.', array['Con phân tích truyện nào? Nhân vật chính có nét gì nổi bật?']::text[]),
  ('l8_van_gioi_thieu_ve_mot_cuon_sach_truyen', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 64, 'Giới thiệu về một cuốn sách (truyện)', 'Nói – nghe: giới thiệu cuốn truyện yêu thích — tác giả, nội dung, điều tâm đắc.', array['Con giới thiệu cuốn nào? Nói thử cho bố mẹ nghe.']::text[]),
  ('l8_van_cung_co_mo_rong_trang_32', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 65, 'Củng cố, mở rộng trang 32', 'Ôn truyện và thơ đã học trong bài 6.', array['Ba văn bản của bài 6 cùng nói về điều gì trong cuộc sống?']::text[]),
  ('l8_van_thuc_hanh_doc_chiec_la_cuoi_cung', 'm_van', 8, 2, 'Bài 6: Chân dung cuộc sống', 66, 'Thực hành đọc: Chiếc lá cuối cùng', 'O. Hen-ri: cụ Bơ-men vẽ chiếc lá thường xuân trong đêm bão để cứu Giôn-xi, rồi mất vì viêm phổi — kiệt tác của tình thương.', array['Ai đã vẽ chiếc lá cuối cùng? → cụ Bơ-men']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_36', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 67, 'Tri thức ngữ văn trang 36', 'Thơ tự do: không cố định số chữ, số câu; nhịp, vần linh hoạt; hình ảnh và biện pháp tu từ; thành ngữ.', array['Thơ tự do khác thơ Đường luật ở chỗ nào? → không bị ràng buộc số câu, số chữ, niêm luật']::text[]),
  ('l8_van_dong_chi', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 68, 'Đồng chí', 'Chính Hữu (1948): tình đồng chí của người lính chống Pháp — cùng cảnh nghèo, cùng chia sẻ gian khổ, sát cánh bên nhau; hình ảnh "Đầu súng trăng treo".', array['Câu thơ cuối bài là gì? → Đầu súng trăng treo', 'Tình đồng chí bắt nguồn từ đâu? → cùng cảnh ngộ nghèo khó, cùng lí tưởng']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_40', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 69, 'Thực hành tiếng Việt trang 40', 'Biện pháp tu từ (so sánh, ẩn dụ, hoán dụ…) và nghĩa của từ, thành ngữ trong thơ.', array['"Nước mặn đồng chua" là thành ngữ chỉ gì? → vùng đất nghèo, khó canh tác']::text[]),
  ('l8_van_la_do', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 70, 'Lá đỏ', 'Nguyễn Đình Thi (1974): cuộc gặp trên đường Trường Sơn với "em gái tiền phương" giữa rừng lá đỏ, đoàn quân ra trận, lời hẹn "gặp nhé giữa Sài Gòn".', array['Bài thơ viết ở đâu, năm nào? → Trường Sơn, 1974']::text[]),
  ('l8_van_nhung_ngoi_sao_xa_xoi', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 71, 'Những ngôi sao xa xôi', 'Lê Minh Khuê: ba cô gái thanh niên xung phong (Phương Định, Nho, chị Thao) phá bom trên tuyến đường Trường Sơn — dũng cảm, hồn nhiên, giàu mơ mộng.', array['Ba nhân vật nữ tên gì? → Phương Định, Nho, Thao', 'Công việc của họ nguy hiểm thế nào?']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_48', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 72, 'Thực hành tiếng Việt trang 48', 'Biện pháp tu từ điệp ngữ, đảo ngữ, so sánh trong thơ và tác dụng nhấn mạnh, gợi cảm.', array['Điệp ngữ là gì? → lặp lại từ ngữ để nhấn mạnh']::text[]),
  ('l8_van_tap_lam_mot_bai_tho_tu_do', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 73, 'Tập làm một bài thơ tự do', 'Viết vài câu thơ tự do về một hình ảnh, cảm xúc của chính mình.', array['Con đọc bài thơ con làm cho cả nhà nghe.']::text[]),
  ('l8_van_viet_doan_van_ghi_lai_cam_nghi_ve_mot_bai_tho_tu_do', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 74, 'Viết đoạn văn ghi lại cảm nghĩ về một bài thơ tự do', 'Đoạn văn nêu cảm xúc về nội dung và nghệ thuật của một bài thơ tự do đã đọc.', array['Con viết về bài thơ nào? Điều gì làm con xúc động?']::text[]),
  ('l8_van_thao_luan_y_kien_ve_mot_van_de_doi_song_phu_hop_voi_lua_tuoi_duoc_goi_ra_tu_tac', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 75, 'Thảo luận ý kiến về một vấn đề đời sống phù hợp với lứa tuổi (được gợi ra từ tác phẩm văn học đã học)', 'Nói – nghe: từ tác phẩm đã học, nêu và bàn một vấn đề đời sống (tình bạn, lí tưởng, lòng dũng cảm…).', array['Nhóm con thảo luận vấn đề gì? Ý kiến của con ra sao?']::text[]),
  ('l8_van_cung_co_mo_rong_trang_56', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 76, 'Củng cố, mở rộng trang 56', 'Ôn thơ tự do và truyện đã học trong bài 7.', array['Các tác phẩm bài 7 cùng nói về ai? → người lính, thanh niên xung phong thời chiến']::text[]),
  ('l8_van_thuc_hanh_doc_bai_tho_ve_tieu_doi_xe_khong_kinh', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 77, 'Thực hành đọc: Bài thơ về tiểu đội xe không kính', 'Phạm Tiến Duật: người lính lái xe Trường Sơn lạc quan, ngang tàng trong những chiếc xe không kính vì bom đạn — "chỉ cần trong xe có một trái tim".', array['Vì sao xe không có kính? → bom giật, bom rung làm kính vỡ']::text[]),
  ('l8_van_doc_mo_rong_trang_58', 'm_van', 8, 2, 'Bài 7: Tin yêu và ước vọng', 78, 'Đọc mở rộng trang 58', 'Tự chọn đọc thơ tự do, truyện và ghi nhật kí đọc.', array['Con đọc thêm bài thơ nào? Thích câu nào nhất?']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_60', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 79, 'Tri thức ngữ văn trang 60', 'Văn bản nghị luận văn học: luận đề, luận điểm, lí lẽ và bằng chứng lấy từ tác phẩm; thành phần biệt lập trong câu.', array['Bằng chứng trong nghị luận văn học lấy từ đâu? → từ chính tác phẩm']::text[]),
  ('l8_van_nha_tho_cua_que_huong_lang_canh_viet_nam', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 80, 'Nhà thơ của quê hương làng cảnh Việt Nam', 'Xuân Diệu viết về Nguyễn Khuyến qua chùm ba bài thơ thu (Thu điếu, Thu vịnh, Thu ẩm) — nhà thơ của làng quê Việt Nam.', array['Xuân Diệu gọi Nguyễn Khuyến là gì? → nhà thơ của quê hương làng cảnh Việt Nam', 'Ba bài thơ thu của Nguyễn Khuyến là gì? → Thu điếu, Thu vịnh, Thu ẩm']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_66', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 81, 'Thực hành tiếng Việt trang 66', 'Thành phần biệt lập: tình thái (có lẽ, chắc chắn, hình như) và cảm thán (ôi, trời ơi) — không tham gia vào nghĩa sự việc của câu.', array['"Có lẽ trời sắp mưa" — "có lẽ" là thành phần gì? → tình thái']::text[]),
  ('l8_van_doc_van_cuoc_choi_tim_y_nghia', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 82, 'Đọc văn – cuộc chơi tìm ý nghĩa', 'Trần Đình Sử: đọc văn là quá trình người đọc tự tìm ra ý nghĩa; tác phẩm có nhiều cách hiểu; việc đọc gắn với trải nghiệm của mỗi người.', array['Theo tác giả, ý nghĩa của tác phẩm do ai tạo ra? → cả người viết lẫn người đọc']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_69', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 83, 'Thực hành tiếng Việt trang 69', 'Thành phần biệt lập: gọi – đáp (này, thưa, ơi) và chêm xen (phần phụ chú đặt trong ngoặc đơn hoặc giữa hai dấu gạch ngang).', array['Phần chêm xen thường đặt trong dấu gì? → ngoặc đơn hoặc hai dấu gạch ngang']::text[]),
  ('l8_van_xe_dem', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 84, 'Xe đêm', 'Truyện của Pau-xtốp-xki về nhà văn An-đéc-xen trên chuyến xe đêm: ông tưởng tượng và kể về tương lai hạnh phúc của những cô gái — sức mạnh của trí tưởng tượng và lòng nhân hậu.', array['Nhân vật nhà văn trong truyện là ai? → An-đéc-xen']::text[]),
  ('l8_van_viet_bai_van_phan_tich_mot_tac_pham_truyen_2', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 85, 'Viết bài văn phân tích một tác phẩm (truyện)', 'Phân tích một truyện: chủ đề, nhân vật, cốt truyện, nghệ thuật; lập luận có bằng chứng.', array['Con chọn truyện nào? Luận điểm chính là gì?']::text[]),
  ('l8_van_trinh_bay_y_kien_ve_mot_van_de_xa_hoi_van_hoc_trong_doi_song_hien_nay', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 86, 'Trình bày ý kiến về một vấn đề xã hội (văn học trong đời sống hiện nay)', 'Nói – nghe: văn học còn cần thiết trong thời đại số không, vì sao.', array['Theo con, đọc văn học có ích gì cho cuộc sống bây giờ?']::text[]),
  ('l8_van_cung_co_mo_rong_trang_82', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 87, 'Củng cố, mở rộng trang 82', 'Ôn văn bản nghị luận văn học.', array['Hai bài nghị luận văn học đã học bàn về điều gì?']::text[]),
  ('l8_van_thuc_hanh_doc_nang_moi_su_thanh_thuc_cua_mot_tam_hon_giau_mo_mong', 'm_van', 8, 2, 'Bài 8: Nhà văn và trang viết', 88, 'Thực hành đọc: Nắng mới – sự thành thực của một tâm hồn giàu mơ mộng', 'Bài phê bình (Lê Quang Hưng) về bài thơ "Nắng mới" của Lưu Trọng Lư: nỗi nhớ mẹ chân thành, mơ mộng.', array['Bài thơ "Nắng mới" nói về ai? → người mẹ']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_87', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 89, 'Tri thức ngữ văn trang 87', 'Văn bản thông tin giải thích một hiện tượng tự nhiên; văn bản kiến nghị; các kiểu câu theo mục đích nói; câu phủ định và câu khẳng định.', array['Văn bản thông tin khác văn bản nghị luận ở chỗ nào? → cung cấp thông tin khách quan, không nhằm thuyết phục']::text[]),
  ('l8_van_mien_chau_tho_song_cuu_long_can_chuyen_doi_tu_song_chung_sang_chao_don_lu', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 90, 'Miền châu thổ sông Cửu Long cần chuyển đổi từ sống chung sang chào đón lũ', 'Lê Anh Tuấn: lũ ở đồng bằng sông Cửu Long mang phù sa, tôm cá, rửa phèn mặn — là nguồn lợi chứ không chỉ là tai họa, nên cần "chào đón" thay vì chỉ "sống chung".', array['Lũ mang lại lợi ích gì cho đồng bằng? → phù sa, thủy sản, rửa phèn mặn']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_93', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 91, 'Thực hành tiếng Việt trang 93', 'Các kiểu câu phân loại theo mục đích nói: câu kể, câu hỏi, câu cảm, câu khiến và dấu hiệu nhận biết.', array['"Con làm bài đi!" là kiểu câu gì? → câu khiến']::text[]),
  ('l8_van_choang_ngop_va_dau_don_nhung_canh_bao_tu_loat_phim_hanh_tinh_cua_chung_ta', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 92, 'Choáng ngợp và đau đớn những cảnh báo từ loạt phim Hành tinh của chúng ta', 'Bài giới thiệu (Lâm Lê) về loạt phim tài liệu "Our Planet": vẻ đẹp choáng ngợp của thiên nhiên và lời cảnh báo đau đớn về sự tàn phá của con người.', array['Loạt phim cảnh báo điều gì? → thiên nhiên đang bị con người tàn phá']::text[]),
  ('l8_van_dien_tu_ung_khau_cua_thu_linh_da_do_xi_at_ton', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 93, 'Diễn từ ứng khẩu của thủ lĩnh da đỏ Xi-át-tơn', 'Bài nói của thủ lĩnh Xi-át-tơn (1854) đáp lại đề nghị mua đất: đất là mẹ, mọi vật đều thiêng liêng; con người thuộc về đất chứ đất không thuộc về con người.', array['Người da đỏ coi đất là gì? → người mẹ, thiêng liêng']::text[]),
  ('l8_van_thuc_hanh_tieng_viet_trang_101', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 94, 'Thực hành tiếng Việt trang 101', 'Câu phủ định (có không, chưa, chẳng…) và câu khẳng định; phủ định miêu tả và phủ định bác bỏ; phủ định của phủ định.', array['"Không phải nó không học" nghĩa là gì? → nó có học (phủ định của phủ định thành khẳng định)']::text[]),
  ('l8_van_viet_van_ban_thuyet_minh_giai_thich_mot_hien_tuong_tu_nhien', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 95, 'Viết văn bản thuyết minh giải thích một hiện tượng tự nhiên', 'Giới thiệu hiện tượng (mưa, cầu vồng, thủy triều…), giải thích nguyên nhân, diễn biến, tác động; dùng số liệu, hình ảnh.', array['Con chọn hiện tượng gì? Nguyên nhân của nó là gì?']::text[]),
  ('l8_van_viet_van_ban_kien_nghi_ve_mot_van_de_cua_doi_song', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 96, 'Viết văn bản kiến nghị về một vấn đề của đời sống', 'Viết đúng thể thức: quốc hiệu, tên văn bản, nơi nhận, nội dung kiến nghị, đề xuất, ngày tháng, chữ kí.', array['Con kiến nghị vấn đề gì, gửi ai?']::text[]),
  ('l8_van_thao_luan_ve_mot_van_de_trong_doi_song_phu_hop_voi_lua_tuoi_to_chuc_hop_li_ne_ne', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 97, 'Thảo luận về một vấn đề trong đời sống phù hợp với lứa tuổi (tổ chức hợp lí nề nếp sinh hoạt của bản thân)', 'Nói – nghe: bàn về giờ giấc học, ngủ, chơi, dùng điện thoại sao cho hợp lí.', array['Con định sắp xếp lại nề nếp sinh hoạt của mình thế nào?']::text[]),
  ('l8_van_cung_co_mo_rong_trang_111', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 98, 'Củng cố, mở rộng trang 111', 'Ôn văn bản thông tin.', array['Ba văn bản của bài 9 cùng nhắc con người điều gì? → sống hài hòa với thiên nhiên']::text[]),
  ('l8_van_thuc_hanh_doc_dau_chan_sinh_thai_cua_moi_nguoi_va_thong_diep_tu_trai_dat', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 99, 'Thực hành đọc: "Dấu chân sinh thái" của mỗi người và thông điệp từ Trái Đất', 'Văn bản thông tin: dấu chân sinh thái đo mức tiêu thụ tài nguyên của mỗi người; cần giảm để Trái Đất kịp phục hồi.', array['Dấu chân sinh thái là gì? → thước đo lượng tài nguyên một người tiêu thụ']::text[]),
  ('l8_van_doc_mo_rong_trang_114', 'm_van', 8, 2, 'Bài 9: Hôm nay và ngày mai', 100, 'Đọc mở rộng trang 114', 'Tự chọn đọc văn bản thông tin, nghị luận và ghi nhật kí đọc.', array['Con đọc được thông tin gì mới về môi trường?']::text[]),
  ('l8_van_tri_thuc_ngu_van_trang_116', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 101, 'Tri thức ngữ văn trang 116', 'Đọc sách có mục tiêu và phương pháp; giới thiệu sách; nhan đề và ý nghĩa của nhan đề.', array['Con đặt mục tiêu đọc bao nhiêu cuốn trong dự án này?']::text[]),
  ('l8_van_doc_nhu_mot_hanh_trinh', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 102, 'Đọc như một hành trình', 'Lập kế hoạch đọc, chọn sách theo chủ đề, ghi chép trong quá trình đọc.', array['Con chọn chủ đề đọc gì? Danh sách sách gồm những cuốn nào?']::text[]),
  ('l8_van_doc_nhu_mot_cuoc_tham_hiem', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 103, 'Đọc như một cuộc thám hiểm', 'Khám phá sách bằng những câu hỏi mới: đọc thơ, truyện, văn bản thông tin từ góc nhìn khác.', array['Con phát hiện điều gì bất ngờ trong cuốn đang đọc?']::text[]),
  ('l8_van_doc_de_dong_hanh_va_chia_se', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 104, 'Đọc để đồng hành và chia sẻ', 'Chia sẻ điều tâm đắc, trao đổi với bạn về sách đã đọc.', array['Con chia sẻ cuốn sách với ai? Bạn nói gì?']::text[]),
  ('l8_van_viet_bai_thuyet_minh_gioi_thieu_cuon_sach_yeu_thich', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 105, 'Viết bài thuyết minh giới thiệu cuốn sách yêu thích', 'Bài thuyết minh: tác giả, nội dung, giá trị, vì sao nên đọc.', array['Con giới thiệu cuốn gì? Lí do nên đọc là gì?']::text[]),
  ('l8_van_viet_mot_nhan_de_va_sang_tao_mot_tac_pham_moi', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 106, 'Viết một nhan đề và sáng tạo một tác phẩm mới', 'Từ ý tưởng của sách đã đọc, thử sáng tác truyện hoặc thơ ngắn và đặt nhan đề.', array['Nhan đề tác phẩm của con là gì? Đọc cho bố mẹ nghe.']::text[]),
  ('l8_van_ve_dich_ngay_hoi_voi_sach', 'm_van', 8, 2, 'Bài 10: Sách – người bạn đồng hành', 107, 'Về đích: Ngày hội với sách', 'Trình bày sản phẩm của dự án đọc sách trước lớp (giới thiệu sách, sáng tác, poster…).', array['Con trình bày sản phẩm gì trong ngày hội?']::text[]),
  ('l8_van_on_tap_hoc_ki_2', 'm_van', 8, 2, 'Ôn tập học kì II', 108, 'Ôn tập học kì 2', 'Hệ thống các thể loại học kì II (truyện, thơ tự do, nghị luận văn học, văn bản thông tin), kiến thức tiếng Việt và các kiểu bài viết.', array['Con kể tên các thể loại đã học trong học kì II.']::text[]),
  ('l8_van_a_on_tap_kien_thuc_on_tap_hoc_ki_2', 'm_van', 8, 2, 'Ôn tập học kì II', 109, 'A. Ôn tập kiến thức (Ôn tập học kì 2)', 'Bảng tổng kết văn bản – thể loại; tiếng Việt: trợ từ, thán từ, thành phần biệt lập, kiểu câu, câu phủ định.', array['Con cho ví dụ về thành phần biệt lập.']::text[]),
  ('l8_van_soan_bai_phieu_hoc_tap_so_1_2', 'm_van', 8, 2, 'Ôn tập học kì II', 110, 'Soạn bài Phiếu học tập số 1', 'Luyện đọc hiểu văn bản mới và viết theo đề tương tự đề kiểm tra cuối năm.', array['Con làm phiếu này mất bao lâu? Câu nào khó nhất?']::text[]),
  ('l8_van_soan_bai_phieu_hoc_tap_so_2_2', 'm_van', 8, 2, 'Ôn tập học kì II', 111, 'Soạn bài Phiếu học tập số 2', 'Luyện đọc hiểu và viết, đề số 2, theo cấu trúc đề kiểm tra cuối năm.', array['Con tự chấm được bao nhiêu điểm phần đọc hiểu?']::text[]),
  ('l8_anh_getting_started_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 1, 'Getting Started (Unit 1: Leisure time)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_a_closer_look_1_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 2, 'A Closer Look 1 (Unit 1: Leisure time)', 'Từ vựng và phát âm. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_a_closer_look_2_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 3, 'A Closer Look 2 (Unit 1: Leisure time)', 'Ngữ pháp: động từ chỉ sở thích (like, love, enjoy, hate, prefer, fancy…) đi với V-ing hoặc to V. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_communication_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 4, 'Communication (Unit 1: Leisure time)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_skills_1_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 5, 'Skills 1 (Unit 1: Leisure time)', 'Đọc hiểu và nói. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_skills_2_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 6, 'Skills 2 (Unit 1: Leisure time)', 'Nghe và viết. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_looking_back_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 7, 'Looking Back (Unit 1: Leisure time)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_project_unit_1_leisure_time', 'm_anh', 8, 1, 'Unit 1: Leisure time', 8, 'Project (Unit 1: Leisure time)', 'Dự án nhóm về chủ đề của unit. Chủ đề hoạt động lúc rảnh (DIY, làm đồ thủ công, lướt mạng, chơi thể thao). Từ vựng về sở thích; phát âm cụm phụ âm /br/ và /kl/.', array['Con thích làm gì lúc rảnh? Nói bằng tiếng Anh: "I enjoy…", "I love… ing".', 'Sau "enjoy" dùng V-ing hay to V? → V-ing']::text[]),
  ('l8_anh_getting_started_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 9, 'Getting Started (Unit 2: Life in the countryside)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_a_closer_look_1_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 10, 'A Closer Look 1 (Unit 2: Life in the countryside)', 'Từ vựng và phát âm. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_a_closer_look_2_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 11, 'A Closer Look 2 (Unit 2: Life in the countryside)', 'Ngữ pháp: so sánh hơn của trạng từ (faster, more slowly, better, worse). Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_communication_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 12, 'Communication (Unit 2: Life in the countryside)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_skills_1_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 13, 'Skills 1 (Unit 2: Life in the countryside)', 'Đọc hiểu và nói. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_skills_2_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 14, 'Skills 2 (Unit 2: Life in the countryside)', 'Nghe và viết. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_looking_back_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 15, 'Looking Back (Unit 2: Life in the countryside)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_project_unit_2_life_in_the_countryside', 'm_anh', 8, 1, 'Unit 2: Life in the countryside', 16, 'Project (Unit 2: Life in the countryside)', 'Dự án nhóm về chủ đề của unit. Chủ đề cuộc sống nông thôn (harvest, herd buffaloes, paddy field, cattle). Từ vựng về việc đồng áng; phát âm /ə/ và /ɪ/ trong từ nhiều âm tiết.', array['So sánh hơn của "carefully" là gì? → more carefully', 'Kể ba từ tiếng Anh về nông thôn.']::text[]),
  ('l8_anh_getting_started_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 17, 'Getting Started (Unit 3: Teenagers)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_a_closer_look_1_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 18, 'A Closer Look 1 (Unit 3: Teenagers)', 'Từ vựng và phát âm. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_a_closer_look_2_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 19, 'A Closer Look 2 (Unit 3: Teenagers)', 'Ngữ pháp: câu đơn và câu ghép nối bằng and, but, or, so. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_communication_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 20, 'Communication (Unit 3: Teenagers)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_skills_1_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 21, 'Skills 1 (Unit 3: Teenagers)', 'Đọc hiểu và nói. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_skills_2_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 22, 'Skills 2 (Unit 3: Teenagers)', 'Nghe và viết. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_looking_back_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 23, 'Looking Back (Unit 3: Teenagers)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_project_unit_3_teenagers', 'm_anh', 8, 1, 'Unit 3: Teenagers', 24, 'Project (Unit 3: Teenagers)', 'Dự án nhóm về chủ đề của unit. Chủ đề tuổi teen: áp lực học tập, bạn bè, mạng xã hội, hoạt động ngoại khóa. Từ vựng về stress và cách giải tỏa; phát âm /ʊ/ và /uː/.', array['Nối "I was tired" và "I finished my homework" bằng "but".', 'Từ nào dùng để nối hai vế câu ghép? → and, but, or, so']::text[]),
  ('l8_anh_review_1', 'm_anh', 8, 1, 'Tiếng Anh 8 Global Success — Học kì I', 25, 'Review 1', 'Ôn tập Units 1–3: từ vựng, phát âm, ngữ pháp (V-ing/to V, so sánh hơn của trạng từ, câu ghép) và bốn kĩ năng.', array['Con làm phần Language được bao nhiêu câu đúng?']::text[]),
  ('l8_anh_getting_started_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 26, 'Getting Started (Unit 4: Ethnic groups of Viet Nam)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_a_closer_look_1_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 27, 'A Closer Look 1 (Unit 4: Ethnic groups of Viet Nam)', 'Từ vựng và phát âm. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_a_closer_look_2_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 28, 'A Closer Look 2 (Unit 4: Ethnic groups of Viet Nam)', 'Ngữ pháp: câu hỏi Yes/No và Wh-; danh từ đếm được và không đếm được với some/any, much/many, a little/a few. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_communication_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 29, 'Communication (Unit 4: Ethnic groups of Viet Nam)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_skills_1_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 30, 'Skills 1 (Unit 4: Ethnic groups of Viet Nam)', 'Đọc hiểu và nói. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_skills_2_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 31, 'Skills 2 (Unit 4: Ethnic groups of Viet Nam)', 'Nghe và viết. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_looking_back_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 32, 'Looking Back (Unit 4: Ethnic groups of Viet Nam)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_project_unit_4_ethnic_groups_of_viet_nam', 'm_anh', 8, 1, 'Unit 4: Ethnic groups of Viet Nam', 33, 'Project (Unit 4: Ethnic groups of Viet Nam)', 'Dự án nhóm về chủ đề của unit. Chủ đề các dân tộc Việt Nam (Tày, Thái, Mường, Khmer…; trang phục, lễ hội, nhà sàn). Từ vựng về văn hóa dân tộc; phát âm /k/ /g/.', array['"Rice" đếm được hay không đếm được? → không đếm được', 'Đặt một câu hỏi Wh- về nơi sinh sống của người Thái.']::text[]),
  ('l8_anh_getting_started_unit_5_our_customs_and_traditions', 'm_anh', 8, 1, 'Unit 5: Our customs and traditions', 34, 'Getting Started (Unit 5: Our customs and traditions)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề phong tục, truyền thống (Tết, thờ cúng tổ tiên, phép tắc trên bàn ăn). Từ vựng về phong tục; phát âm /spr/ /str/.', array['Khi nào dùng "an"? → trước từ bắt đầu bằng nguyên âm, ví dụ an apple', 'Kể một phong tục ngày Tết bằng tiếng Anh.']::text[]),
  ('l8_anh_a_closer_look_1_unit_5_our_customs_and_traditions', 'm_anh', 8, 1, 'Unit 5: Our customs and traditions', 35, 'A Closer Look 1 (Unit 5: Our customs and traditions)', 'Từ vựng và phát âm. Chủ đề phong tục, truyền thống (Tết, thờ cúng tổ tiên, phép tắc trên bàn ăn). Từ vựng về phong tục; phát âm /spr/ /str/.', array['Khi nào dùng "an"? → trước từ bắt đầu bằng nguyên âm, ví dụ an apple', 'Kể một phong tục ngày Tết bằng tiếng Anh.']::text[]),
  ('l8_anh_a_closer_look_2_unit_5_our_customs_and_traditions', 'm_anh', 8, 1, 'Unit 5: Our customs and traditions', 36, 'A Closer Look 2 (Unit 5: Our customs and traditions)', 'Ngữ pháp: mạo từ a, an, the và trường hợp không dùng mạo từ. Chủ đề phong tục, truyền thống (Tết, thờ cúng tổ tiên, phép tắc trên bàn ăn). Từ vựng về phong tục; phát âm /spr/ /str/.', array['Khi nào dùng "an"? → trước từ bắt đầu bằng nguyên âm, ví dụ an apple', 'Kể một phong tục ngày Tết bằng tiếng Anh.']::text[]),
