  ('l8_anh_looking_back_unit_5_our_customs_and_traditions', 'm_anh', 8, 1, 'Unit 5: Our customs and traditions', 40, 'Looking Back (Unit 5: Our customs and traditions)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề phong tục, truyền thống (Tết, thờ cúng tổ tiên, phép tắc trên bàn ăn). Từ vựng về phong tục; phát âm /spr/ /str/.', array['Khi nào dùng "an"? → trước từ bắt đầu bằng nguyên âm, ví dụ an apple', 'Kể một phong tục ngày Tết bằng tiếng Anh.']::text[]),
  ('l8_anh_project_unit_5_our_customs_and_traditions', 'm_anh', 8, 1, 'Unit 5: Our customs and traditions', 41, 'Project (Unit 5: Our customs and traditions)', 'Dự án nhóm về chủ đề của unit. Chủ đề phong tục, truyền thống (Tết, thờ cúng tổ tiên, phép tắc trên bàn ăn). Từ vựng về phong tục; phát âm /spr/ /str/.', array['Khi nào dùng "an"? → trước từ bắt đầu bằng nguyên âm, ví dụ an apple', 'Kể một phong tục ngày Tết bằng tiếng Anh.']::text[]),
  ('l8_anh_getting_started_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 42, 'Getting Started (Unit 6: Lifestyles)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_a_closer_look_1_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 43, 'A Closer Look 1 (Unit 6: Lifestyles)', 'Từ vựng và phát âm. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_a_closer_look_2_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 44, 'A Closer Look 2 (Unit 6: Lifestyles)', 'Ngữ pháp: thì tương lai đơn will/won''t và câu điều kiện loại 1 (If + hiện tại đơn, will). Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_communication_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 45, 'Communication (Unit 6: Lifestyles)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_skills_1_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 46, 'Skills 1 (Unit 6: Lifestyles)', 'Đọc hiểu và nói. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_skills_2_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 47, 'Skills 2 (Unit 6: Lifestyles)', 'Nghe và viết. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_looking_back_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 48, 'Looking Back (Unit 6: Lifestyles)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_project_unit_6_lifestyles', 'm_anh', 8, 1, 'Unit 6: Lifestyles', 49, 'Project (Unit 6: Lifestyles)', 'Dự án nhóm về chủ đề của unit. Chủ đề lối sống (lành mạnh, thời gian dùng màn hình, lối sống tương lai). Từ vựng về thói quen; phát âm /brɪ/ /brəʊ/.', array['"If it rains, I ___ stay home." → will', 'Mười năm nữa lối sống sẽ thay đổi thế nào? Nói một câu với "will".']::text[]),
  ('l8_anh_review_2', 'm_anh', 8, 1, 'Tiếng Anh 8 Global Success — Học kì I', 50, 'Review 2', 'Ôn tập Units 4–6: từ vựng, phát âm, ngữ pháp (câu hỏi, danh từ đếm được, mạo từ, will, điều kiện loại 1) và bốn kĩ năng.', array['Con còn nhầm phần ngữ pháp nào nhất?']::text[]),
  ('l8_anh_getting_started_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 51, 'Getting Started (Unit 7: Environmental protection)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
  ('l8_anh_a_closer_look_1_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 52, 'A Closer Look 1 (Unit 7: Environmental protection)', 'Từ vựng và phát âm. Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
  ('l8_anh_a_closer_look_2_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 53, 'A Closer Look 2 (Unit 7: Environmental protection)', 'Ngữ pháp: câu phức với mệnh đề trạng ngữ chỉ thời gian (when, while, before, after, as soon as). Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
  ('l8_anh_communication_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 54, 'Communication (Unit 7: Environmental protection)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
  ('l8_anh_skills_1_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 55, 'Skills 1 (Unit 7: Environmental protection)', 'Đọc hiểu và nói. Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
