  ('l8_anh_looking_back_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 57, 'Looking Back (Unit 7: Environmental protection)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
  ('l8_anh_project_unit_7_environmental_protection', 'm_anh', 8, 2, 'Unit 7: Environmental protection', 58, 'Project (Unit 7: Environmental protection)', 'Dự án nhóm về chủ đề của unit. Chủ đề bảo vệ môi trường (ô nhiễm, 3R: reduce – reuse – recycle, tiết kiệm năng lượng). Từ vựng về môi trường; phát âm trọng âm từ hai âm tiết.', array['Đặt một câu với "when": "When I finish my homework, …".', '3R là gì? → reduce, reuse, recycle']::text[]),
  ('l8_anh_getting_started_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 59, 'Getting Started (Unit 8: Shopping)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_a_closer_look_1_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 60, 'A Closer Look 1 (Unit 8: Shopping)', 'Từ vựng và phát âm. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_a_closer_look_2_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 61, 'A Closer Look 2 (Unit 8: Shopping)', 'Ngữ pháp: trạng từ chỉ tần suất (always, usually, often, sometimes, rarely, never) và vị trí trong câu. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_communication_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 62, 'Communication (Unit 8: Shopping)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_skills_1_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 63, 'Skills 1 (Unit 8: Shopping)', 'Đọc hiểu và nói. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_skills_2_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 64, 'Skills 2 (Unit 8: Shopping)', 'Nghe và viết. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_looking_back_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 65, 'Looking Back (Unit 8: Shopping)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_project_unit_8_shopping', 'm_anh', 8, 2, 'Unit 8: Shopping', 66, 'Project (Unit 8: Shopping)', 'Dự án nhóm về chủ đề của unit. Chủ đề mua sắm (trung tâm thương mại, chợ, mua hàng online, mặc cả). Từ vựng về mua sắm; phát âm trọng âm từ ba âm tiết.', array['"Always" đặt trước hay sau động từ thường? → trước động từ thường, sau "be"', 'Con thích mua ở chợ hay online? Nói bằng tiếng Anh.']::text[]),
  ('l8_anh_getting_started_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 67, 'Getting Started (Unit 9: Natural disasters)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
  ('l8_anh_a_closer_look_1_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 68, 'A Closer Look 1 (Unit 9: Natural disasters)', 'Từ vựng và phát âm. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
  ('l8_anh_a_closer_look_2_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 69, 'A Closer Look 2 (Unit 9: Natural disasters)', 'Ngữ pháp: thì quá khứ tiếp diễn; quá khứ đơn kết hợp quá khứ tiếp diễn với when/while. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
  ('l8_anh_communication_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 70, 'Communication (Unit 9: Natural disasters)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
  ('l8_anh_skills_1_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 71, 'Skills 1 (Unit 9: Natural disasters)', 'Đọc hiểu và nói. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
