  ('l8_anh_looking_back_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 73, 'Looking Back (Unit 9: Natural disasters)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
  ('l8_anh_project_unit_9_natural_disasters', 'm_anh', 8, 2, 'Unit 9: Natural disasters', 74, 'Project (Unit 9: Natural disasters)', 'Dự án nhóm về chủ đề của unit. Chủ đề thiên tai (earthquake, flood, typhoon, drought, landslide) và cách ứng phó. Từ vựng về thiên tai; ngữ điệu câu.', array['"I ___ (watch) TV when the earthquake happened." → was watching', 'Kể ba loại thiên tai bằng tiếng Anh.']::text[]),
  ('l8_anh_review_3', 'm_anh', 8, 2, 'Tiếng Anh 8 Global Success — Học kì II', 75, 'Review 3', 'Ôn tập Units 7–9: từ vựng, phát âm, ngữ pháp (mệnh đề thời gian, trạng từ tần suất, quá khứ tiếp diễn) và bốn kĩ năng.', array['Con phân biệt được quá khứ đơn và quá khứ tiếp diễn chưa? Cho ví dụ.']::text[]),
  ('l8_anh_getting_started_unit_10_communication_in_the_future', 'm_anh', 8, 2, 'Unit 10: Communication in the future', 76, 'Getting Started (Unit 10: Communication in the future)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề giao tiếp trong tương lai (video call, hologram, telepathy, ngôn ngữ cơ thể). Từ vựng về phương tiện giao tiếp; phát âm trọng âm câu.', array['"___ Monday" dùng giới từ gì? → on', '"___ 7 o''clock" dùng giới từ gì? → at']::text[]),
  ('l8_anh_a_closer_look_1_unit_10_communication_in_the_future', 'm_anh', 8, 2, 'Unit 10: Communication in the future', 77, 'A Closer Look 1 (Unit 10: Communication in the future)', 'Từ vựng và phát âm. Chủ đề giao tiếp trong tương lai (video call, hologram, telepathy, ngôn ngữ cơ thể). Từ vựng về phương tiện giao tiếp; phát âm trọng âm câu.', array['"___ Monday" dùng giới từ gì? → on', '"___ 7 o''clock" dùng giới từ gì? → at']::text[]),
  ('l8_anh_a_closer_look_2_unit_10_communication_in_the_future', 'm_anh', 8, 2, 'Unit 10: Communication in the future', 78, 'A Closer Look 2 (Unit 10: Communication in the future)', 'Ngữ pháp: giới từ chỉ nơi chốn và thời gian (in, on, at, in front of, opposite, under…). Chủ đề giao tiếp trong tương lai (video call, hologram, telepathy, ngôn ngữ cơ thể). Từ vựng về phương tiện giao tiếp; phát âm trọng âm câu.', array['"___ Monday" dùng giới từ gì? → on', '"___ 7 o''clock" dùng giới từ gì? → at']::text[]),
  ('l8_anh_communication_unit_10_communication_in_the_future', 'm_anh', 8, 2, 'Unit 10: Communication in the future', 79, 'Communication (Unit 10: Communication in the future)', 'Giao tiếp: mẫu câu thường dùng theo chủ đề. Chủ đề giao tiếp trong tương lai (video call, hologram, telepathy, ngôn ngữ cơ thể). Từ vựng về phương tiện giao tiếp; phát âm trọng âm câu.', array['"___ Monday" dùng giới từ gì? → on', '"___ 7 o''clock" dùng giới từ gì? → at']::text[]),
