  ('l8_anh_looking_back_unit_10_communication_in_the_future', 'm_anh', 8, 2, 'Unit 10: Communication in the future', 82, 'Looking Back (Unit 10: Communication in the future)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề giao tiếp trong tương lai (video call, hologram, telepathy, ngôn ngữ cơ thể). Từ vựng về phương tiện giao tiếp; phát âm trọng âm câu.', array['"___ Monday" dùng giới từ gì? → on', '"___ 7 o''clock" dùng giới từ gì? → at']::text[]),
  ('l8_anh_project_unit_10_communication_in_the_future', 'm_anh', 8, 2, 'Unit 10: Communication in the future', 83, 'Project (Unit 10: Communication in the future)', 'Dự án nhóm về chủ đề của unit. Chủ đề giao tiếp trong tương lai (video call, hologram, telepathy, ngôn ngữ cơ thể). Từ vựng về phương tiện giao tiếp; phát âm trọng âm câu.', array['"___ Monday" dùng giới từ gì? → on', '"___ 7 o''clock" dùng giới từ gì? → at']::text[]),
  ('l8_anh_getting_started_unit_11_science_and_technology', 'm_anh', 8, 2, 'Unit 11: Science and technology', 84, 'Getting Started (Unit 11: Science and technology)', 'Hội thoại mở đầu, làm quen từ vựng và ngữ pháp của unit. Chủ đề khoa học và công nghệ (robot, AI, phát minh, cuộc sống thông minh). Từ vựng về công nghệ; ngữ điệu câu hỏi.', array['Chuyển "I am tired" sang câu tường thuật. → He said (that) he was tired.', 'Kể một phát minh con thấy hữu ích và vì sao.']::text[]),
