  ('l8_anh_skills_1_unit_12_life_on_other_planets', 'm_anh', 8, 2, 'Unit 12: Life on other planets', 96, 'Skills 1 (Unit 12: Life on other planets)', 'Đọc hiểu và nói. Chủ đề sự sống ngoài hành tinh (alien, UFO, planet, galaxy, spaceship). Từ vựng về vũ trụ; ngữ điệu câu.', array['Chuyển "Do you like it?" sang tường thuật. → She asked me if I liked it.', 'Con có tin có người ngoài hành tinh không? Nói một câu tiếng Anh.']::text[]),
  ('l8_anh_skills_2_unit_12_life_on_other_planets', 'm_anh', 8, 2, 'Unit 12: Life on other planets', 97, 'Skills 2 (Unit 12: Life on other planets)', 'Nghe và viết. Chủ đề sự sống ngoài hành tinh (alien, UFO, planet, galaxy, spaceship). Từ vựng về vũ trụ; ngữ điệu câu.', array['Chuyển "Do you like it?" sang tường thuật. → She asked me if I liked it.', 'Con có tin có người ngoài hành tinh không? Nói một câu tiếng Anh.']::text[]),
  ('l8_anh_looking_back_unit_12_life_on_other_planets', 'm_anh', 8, 2, 'Unit 12: Life on other planets', 98, 'Looking Back (Unit 12: Life on other planets)', 'Ôn tập từ vựng, ngữ pháp cả unit. Chủ đề sự sống ngoài hành tinh (alien, UFO, planet, galaxy, spaceship). Từ vựng về vũ trụ; ngữ điệu câu.', array['Chuyển "Do you like it?" sang tường thuật. → She asked me if I liked it.', 'Con có tin có người ngoài hành tinh không? Nói một câu tiếng Anh.']::text[]),
  ('l8_anh_project_unit_12_life_on_other_planets', 'm_anh', 8, 2, 'Unit 12: Life on other planets', 99, 'Project (Unit 12: Life on other planets)', 'Dự án nhóm về chủ đề của unit. Chủ đề sự sống ngoài hành tinh (alien, UFO, planet, galaxy, spaceship). Từ vựng về vũ trụ; ngữ điệu câu.', array['Chuyển "Do you like it?" sang tường thuật. → She asked me if I liked it.', 'Con có tin có người ngoài hành tinh không? Nói một câu tiếng Anh.']::text[]),
  ('l8_anh_review_4', 'm_anh', 8, 2, 'Tiếng Anh 8 Global Success — Học kì II', 100, 'Review 4', 'Ôn tập Units 10–12: từ vựng, phát âm, ngữ pháp (giới từ, câu tường thuật) và bốn kĩ năng; ôn cuối năm.', array['Con tự thấy kĩ năng nào yếu nhất: nghe, nói, đọc hay viết?']::text[]),
  ('l8_hoa_bai_1_su_dung_mot_so_hoa_chat_thiet_bi_co_ban_trong_phong_thi_nghiem', 'm_hoa', 8, 1, 'Mở đầu', 1, 'Bài 1: Sử dụng một số hóa chất, thiết bị cơ bản trong phòng thí nghiệm', 'Nhận biết dụng cụ (ống nghiệm, đèn cồn, bình chia độ, ampe kế, vôn kế, joulemeter…), đọc nhãn hóa chất và các quy tắc an toàn khi làm thí nghiệm.', array['Kể ba quy tắc an toàn trong phòng thí nghiệm.', 'Muốn lấy một lượng nhỏ hóa chất lỏng dùng dụng cụ gì? → ống hút nhỏ giọt']::text[]),
  ('l8_hoa_bai_2_phan_ung_hoa_hoc', 'm_hoa', 8, 1, 'Chương 1: Phản ứng hóa học', 2, 'Bài 2: Phản ứng hóa học', 'Biến đổi vật lí (đổi trạng thái, hình dạng, vẫn là chất cũ) và biến đổi hóa học (tạo ra chất mới). Phản ứng hóa học, chất tham gia, sản phẩm; dấu hiệu nhận biết; phản ứng tỏa nhiệt và thu nhiệt.', array['Nước đá tan thành nước là biến đổi gì? → vật lí', 'Đốt tờ giấy là biến đổi gì? → hóa học', 'Dấu hiệu nào cho biết có phản ứng hóa học? → đổi màu, sủi bọt khí, kết tủa, tỏa nhiệt hoặc phát sáng']::text[]),
  ('l8_hoa_bai_3_mol_va_ti_khoi_chat_khi', 'm_hoa', 8, 1, 'Chương 1: Phản ứng hóa học', 3, 'Bài 3: Mol và tỉ khối chất khí', 'Mol là lượng chất chứa 6,022·10²³ hạt; khối lượng mol M (g/mol); ở 25 °C và 1 bar, 1 mol khí chiếm 24,79 lít; tỉ khối cho biết khí này nặng hay nhẹ hơn khí kia.', array['1 mol nước (H₂O) nặng bao nhiêu gam? → 18 g', 'Khí nào nhẹ hơn không khí: H₂ hay CO₂? → H₂']::text[]),
  ('l8_hoa_bai_4_dung_dich_va_nong_do', 'm_hoa', 8, 1, 'Chương 1: Phản ứng hóa học', 4, 'Bài 4: Dung dịch và nồng độ', 'Dung dịch gồm chất tan và dung môi; dung dịch bão hòa; độ tan. Nồng độ phần trăm C% = m chất tan / m dung dịch · 100% và nồng độ mol C_M = n/V.', array['Hòa 10 g muối vào 90 g nước, nồng độ phần trăm bằng? → 10%', 'Pha thêm nước vào dung dịch thì nồng độ tăng hay giảm? → giảm']::text[]),
  ('l8_hoa_bai_5_dinh_luat_bao_toan_khoi_luong_va_phuong_trinh_hoa_hoc', 'm_hoa', 8, 1, 'Chương 1: Phản ứng hóa học', 5, 'Bài 5: Định luật bảo toàn khối lượng và phương trình hóa học', 'Tổng khối lượng chất tham gia bằng tổng khối lượng sản phẩm. Lập phương trình hóa học: viết sơ đồ, cân bằng hệ số; ý nghĩa tỉ lệ số mol.', array['Cân bằng phương trình H₂ + O₂ → H₂O. → 2H₂ + O₂ → 2H₂O', 'Đốt 12 g carbon với 32 g oxygen tạo ra bao nhiêu gam CO₂? → 44 g']::text[]),
  ('l8_hoa_bai_6_tinh_theo_phuong_trinh_hoa_hoc', 'm_hoa', 8, 1, 'Chương 1: Phản ứng hóa học', 6, 'Bài 6: Tính theo phương trình hóa học', 'Từ số mol chất này tính số mol, khối lượng, thể tích chất kia theo tỉ lệ hệ số trong phương trình; hiệu suất phản ứng.', array['Theo 2H₂ + O₂ → 2H₂O, 2 mol H₂ cần bao nhiêu mol O₂? → 1 mol', 'Các bước tính theo phương trình hóa học là gì? → viết phương trình, tính số mol chất đã biết, lập tỉ lệ, tính chất cần tìm']::text[]),
  ('l8_hoa_bai_7_toc_do_phan_ung_va_chat_xuc_tac', 'm_hoa', 8, 1, 'Chương 1: Phản ứng hóa học', 7, 'Bài 7: Tốc độ phản ứng và chất xúc tác', 'Phản ứng có thể nhanh hay chậm; các yếu tố làm tăng tốc độ: nồng độ, nhiệt độ, diện tích tiếp xúc, chất xúc tác (không bị tiêu hao).', array['Vì sao thức ăn để tủ lạnh lâu hỏng hơn? → nhiệt độ thấp làm phản ứng chậm lại', 'Chất xúc tác có bị tiêu hao sau phản ứng không? → không']::text[]),
  ('l8_hoa_bai_8_acid', 'm_hoa', 8, 1, 'Chương 2: Một số hợp chất thông dụng', 8, 'Bài 8: Acid', 'Acid là phân tử có nguyên tử H liên kết với gốc acid, tan trong nước tạo ion H⁺; làm quỳ tím hóa đỏ; tác dụng với kim loại tạo muối và khí hydrogen. Acid thông dụng: HCl, H₂SO₄, CH₃COOH.', array['Acid làm quỳ tím đổi màu gì? → đỏ', 'Giấm ăn chứa acid gì? → acetic acid (CH₃COOH)']::text[]),
  ('l8_hoa_bai_9_base_thang_ph', 'm_hoa', 8, 1, 'Chương 2: Một số hợp chất thông dụng', 9, 'Bài 9: Base. Thang pH', 'Base (kiềm tan trong nước tạo OH⁻) làm quỳ tím hóa xanh, phenolphthalein hóa hồng; acid + base → muối + nước (trung hòa). Thang pH: dưới 7 acid, bằng 7 trung tính, trên 7 base.', array['Dung dịch pH = 3 là môi trường gì? → acid', 'NaOH làm quỳ tím đổi màu gì? → xanh']::text[]),
  ('l8_hoa_bai_10_oxide', 'm_hoa', 8, 1, 'Chương 2: Một số hợp chất thông dụng', 10, 'Bài 10: Oxide', 'Oxide là hợp chất của oxygen với một nguyên tố khác. Phân loại: oxide acid, oxide base, oxide lưỡng tính, oxide trung tính; oxide base tác dụng với acid, oxide acid tác dụng với base.', array['CO₂ là oxide gì? → oxide acid', 'CaO là oxide gì? → oxide base']::text[]),
  ('l8_hoa_bai_11_muoi', 'm_hoa', 8, 1, 'Chương 2: Một số hợp chất thông dụng', 11, 'Bài 11: Muối', 'Muối gồm kim loại (hoặc NH₄) liên kết với gốc acid; tên gọi, tính tan; phản ứng với kim loại, acid, base, muối khác; cách điều chế.', array['Muối ăn có công thức gì? → NaCl (sodium chloride)', 'Acid tác dụng với base tạo ra gì? → muối và nước']::text[]),
  ('l8_hoa_bai_12_phan_bon_hoa_hoc', 'm_hoa', 8, 1, 'Chương 2: Một số hợp chất thông dụng', 12, 'Bài 12: Phân bón hóa học', 'Phân đạm (N), phân lân (P), phân kali (K) và phân NPK; vai trò với cây trồng; bón hợp lí, tác hại khi lạm dụng (ô nhiễm đất, nước).', array['Phân đạm cung cấp nguyên tố gì cho cây? → nitrogen (N)', 'Bón quá nhiều phân hóa học có hại gì?']::text[]),
  ('l8_ly_bai_13_khoi_luong_rieng', 'm_ly', 8, 1, 'Chương 3: Khối lượng riêng và áp suất', 1, 'Bài 13: Khối lượng riêng', 'Khối lượng riêng D = m/V (kg/m³ hoặc g/cm³) cho biết chất nặng hay nhẹ; nước có D = 1000 kg/m³.', array['Khối lượng riêng của nước bằng bao nhiêu? → 1000 kg/m³ = 1 g/cm³', 'Vật nặng 200 g, thể tích 100 cm³ có khối lượng riêng bằng? → 2 g/cm³']::text[]),
  ('l8_ly_bai_14_thuc_hanh_xac_dinh_khoi_luong_rieng', 'm_ly', 8, 1, 'Chương 3: Khối lượng riêng và áp suất', 2, 'Bài 14: Thực hành xác định khối lượng riêng', 'Đo khối lượng bằng cân, thể tích bằng bình chia độ (vật rắn) hoặc bình tràn, rồi tính D; ghi và xử lí số liệu.', array['Đo thể tích vật rắn không thấm nước bằng cách nào? → thả vào bình chia độ, đo phần nước dâng lên']::text[]),
  ('l8_ly_bai_15_ap_suat_tren_mot_be_mat', 'm_ly', 8, 1, 'Chương 3: Khối lượng riêng và áp suất', 3, 'Bài 15: Áp suất trên một bề mặt', 'Áp lực là lực ép vuông góc với mặt bị ép; áp suất p = F/S (đơn vị pascal). Cách tăng, giảm áp suất trong đời sống (dao mài mỏng, xe tăng bản xích rộng).', array['Vì sao dao càng mỏng càng dễ cắt? → diện tích tiếp xúc nhỏ nên áp suất lớn', 'Đơn vị của áp suất là gì? → pascal (Pa)']::text[]),
  ('l8_ly_bai_16_ap_suat_chat_long_ap_suat_khi_quyen', 'm_ly', 8, 1, 'Chương 3: Khối lượng riêng và áp suất', 4, 'Bài 16: Áp suất chất lỏng. Áp suất khí quyển', 'Chất lỏng gây áp suất lên đáy, thành bình và mọi vật trong lòng nó, càng sâu càng lớn; bình thông nhau. Không khí cũng có áp suất (uống bằng ống hút, thí nghiệm bán cầu Ma-đơ-bua).', array['Lặn càng sâu, áp suất nước thế nào? → tăng', 'Vì sao hút được nước qua ống hút? → áp suất khí quyển đẩy nước lên khi trong ống giảm áp']::text[]),
  ('l8_ly_bai_17_luc_day_archimedes', 'm_ly', 8, 1, 'Chương 3: Khối lượng riêng và áp suất', 5, 'Bài 17: Lực đẩy Archimedes', 'Vật nhúng trong chất lỏng bị đẩy lên bằng trọng lượng phần chất lỏng bị chiếm chỗ: F_A = d·V. Vật nổi khi lực đẩy lớn hơn hoặc bằng trọng lượng.', array['Vì sao tàu sắt nổi mà cái đinh sắt chìm? → tàu rỗng, thể tích chiếm chỗ lớn nên lực đẩy lớn hơn trọng lượng', 'Lực đẩy Archimedes phụ thuộc vào gì? → khối lượng riêng chất lỏng và thể tích phần chìm']::text[]),
  ('l8_ly_bai_18_tac_dung_lam_quay_cua_luc_moment_luc', 'm_ly', 8, 1, 'Chương 4: Tác dụng làm quay của lực', 6, 'Bài 18: Tác dụng làm quay của lực. Moment lực', 'Lực làm vật quay quanh trục khi giá của lực không đi qua trục quay. Moment lực đặc trưng cho tác dụng làm quay, càng lớn khi lực càng mạnh và khoảng cách từ trục tới giá của lực càng xa.', array['Vặn ốc bằng cờ lê dài hay ngắn thì dễ hơn? Vì sao? → dài, vì cánh tay đòn lớn nên moment lớn']::text[]),
  ('l8_ly_bai_19_don_bay_va_ung_dung', 'm_ly', 8, 1, 'Chương 4: Tác dụng làm quay của lực', 7, 'Bài 19: Đòn bẩy và ứng dụng', 'Ba loại đòn bẩy theo vị trí điểm tựa; đòn bẩy cho lợi về lực khi cánh tay đòn của lực dài hơn. Ứng dụng: bập bênh, kìm, kéo, xe cút kít, cần câu.', array['Cái kéo là đòn bẩy loại nào? → điểm tựa ở giữa', 'Kể ba dụng cụ trong nhà là đòn bẩy.']::text[]),
  ('l8_ly_bai_20_hien_tuong_nhiem_dien_do_co_xat', 'm_ly', 8, 1, 'Chương 5: Điện', 8, 'Bài 20: Hiện tượng nhiễm điện do cọ xát', 'Cọ xát làm vật nhiễm điện và hút được vật nhẹ; hai loại điện tích dương, âm; cùng loại đẩy nhau, khác loại hút nhau. Giải thích sét, tóc dựng khi chải.', array['Hai vật nhiễm điện cùng loại thì hút hay đẩy nhau? → đẩy', 'Vì sao mùa hanh khô chải tóc thì tóc dựng lên? → tóc và lược nhiễm điện do cọ xát']::text[]),
  ('l8_ly_bai_21_dong_dien_nguon_dien', 'm_ly', 8, 1, 'Chương 5: Điện', 9, 'Bài 21: Dòng điện, nguồn điện', 'Dòng điện là dòng các hạt mang điện dịch chuyển có hướng; nguồn điện (pin, acquy) có hai cực; vật dẫn điện và vật cách điện.', array['Kể ba vật dẫn điện và ba vật cách điện.', 'Pin có mấy cực? → hai cực: dương (+) và âm (−)']::text[]),
  ('l8_ly_bai_22_mach_dien_don_gian', 'm_ly', 8, 1, 'Chương 5: Điện', 10, 'Bài 22: Mạch điện đơn giản', 'Mạch điện kín gồm nguồn, dây dẫn, công tắc, thiết bị tiêu thụ; kí hiệu trong sơ đồ; chiều dòng điện quy ước từ cực dương qua dây dẫn về cực âm.', array['Chiều dòng điện quy ước như thế nào? → từ cực dương qua dây dẫn và thiết bị về cực âm', 'Con vẽ sơ đồ mạch gồm pin, công tắc và bóng đèn.']::text[]),
  ('l8_ly_bai_23_tac_dung_cua_dong_dien', 'm_ly', 8, 1, 'Chương 5: Điện', 11, 'Bài 23: Tác dụng của dòng điện', 'Bốn tác dụng: nhiệt, phát sáng, hóa học, sinh lí; ứng dụng (bàn là, đèn, mạ điện, châm cứu điện) và nguy hiểm khi bị điện giật.', array['Bàn là dùng tác dụng gì của dòng điện? → tác dụng nhiệt', 'Mạ điện là ứng dụng của tác dụng gì? → tác dụng hóa học']::text[]),
  ('l8_ly_bai_24_cuong_do_dong_dien_va_hieu_dien_the', 'm_ly', 8, 1, 'Chương 5: Điện', 12, 'Bài 24: Cường độ dòng điện và hiệu điện thế', 'Cường độ dòng điện I (ampe, A) đo bằng ampe kế mắc nối tiếp; hiệu điện thế U (vôn, V) đo bằng vôn kế mắc song song. Pin tròn 1,5 V.', array['Ampe kế mắc nối tiếp hay song song với bóng đèn? → nối tiếp', 'Đơn vị của hiệu điện thế là gì? → vôn (V)']::text[]),
  ('l8_ly_bai_25_thuc_hanh_do_cuong_do_dong_dien_va_hieu_dien_the', 'm_ly', 8, 1, 'Chương 5: Điện', 13, 'Bài 25: Thực hành đo cường độ dòng điện và hiệu điện thế', 'Lắp mạch, mắc đúng ampe kế và vôn kế, đọc số chỉ, ghi vào bảng và nhận xét.', array['Khi mắc ampe kế cần chú ý gì? → đúng chốt dương âm, mắc nối tiếp, chọn thang đo phù hợp']::text[]),
  ('l8_ly_bai_26_nang_luong_nhiet_va_noi_nang', 'm_ly', 8, 1, 'Chương 6: Nhiệt', 14, 'Bài 26: Năng lượng nhiệt và nội năng', 'Các phân tử luôn chuyển động; năng lượng nhiệt là tổng động năng của chúng; nội năng của vật. Vật nóng lên thì nội năng tăng; đo nhiệt lượng bằng joulemeter (đơn vị J).', array['Vật nóng lên thì các phân tử chuyển động thế nào? → nhanh hơn']::text[]),
  ('l8_ly_bai_27_thuc_hanh_do_nang_luong_nhiet_bang_joulemeter', 'm_ly', 8, 1, 'Chương 6: Nhiệt', 15, 'Bài 27: Thực hành đo năng lượng nhiệt bằng joulemeter', 'Đo nhiệt lượng cần để làm nóng nước bằng joulemeter, ghi số liệu và nhận xét mối liên hệ với độ tăng nhiệt độ.', array['Đun càng lâu thì số chỉ joulemeter thay đổi thế nào? → tăng']::text[]),
  ('l8_ly_bai_28_su_truyen_nhiet', 'm_ly', 8, 1, 'Chương 6: Nhiệt', 16, 'Bài 28: Sự truyền nhiệt', 'Ba cách truyền nhiệt: dẫn nhiệt (chất rắn), đối lưu (chất lỏng, khí), bức xạ nhiệt (kể cả qua chân không). Vật dẫn nhiệt tốt, kém; ứng dụng: phích nước, hiệu ứng nhà kính.', array['Nhiệt từ Mặt Trời truyền xuống Trái Đất bằng cách nào? → bức xạ nhiệt', 'Vì sao quai nồi làm bằng nhựa hoặc gỗ? → dẫn nhiệt kém nên không bị bỏng']::text[]),
  ('l8_ly_bai_29_su_no_vi_nhiet', 'm_ly', 8, 1, 'Chương 6: Nhiệt', 17, 'Bài 29: Sự nở vì nhiệt', 'Chất rắn, lỏng, khí đều nở ra khi nóng lên, co lại khi lạnh đi; chất khí nở nhiều nhất. Ứng dụng và đề phòng: khe hở đường ray, nhiệt kế, băng kép.', array['Vì sao đường ray tàu hỏa có khe hở giữa các thanh? → để ray nở vì nhiệt không bị cong', 'Chất nào nở vì nhiệt nhiều nhất? → chất khí']::text[]),
  ('l8_sinh_bai_30_khai_quat_ve_co_the_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 1, 'Bài 30: Khái quát về cơ thể người', 'Các phần của cơ thể và các hệ cơ quan (vận động, tiêu hóa, tuần hoàn, hô hấp, bài tiết, thần kinh, nội tiết, sinh dục) cùng chức năng phối hợp với nhau.', array['Kể tên năm hệ cơ quan trong cơ thể người.']::text[]),
  ('l8_sinh_bai_31_he_van_dong_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 2, 'Bài 31: Hệ vận động ở người', 'Bộ xương (xương đầu, thân, chi), các khớp và hệ cơ; cấu tạo xương; bệnh loãng xương, cong vẹo cột sống; ý nghĩa của luyện tập và ngồi học đúng tư thế.', array['Ngồi học sai tư thế lâu ngày dễ bị gì? → cong vẹo cột sống', 'Cơ thể người có khoảng bao nhiêu chiếc xương? → khoảng 206']::text[]),
  ('l8_sinh_bai_32_dinh_duong_va_tieu_hoa_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 3, 'Bài 32: Dinh dưỡng và tiêu hóa ở người', 'Các chất dinh dưỡng; cơ quan tiêu hóa (miệng, thực quản, dạ dày, ruột non, ruột già) và quá trình tiêu hóa, hấp thụ; an toàn thực phẩm; bệnh về tiêu hóa.', array['Chất dinh dưỡng được hấp thụ chủ yếu ở đâu? → ruột non', 'Một bữa ăn cân đối cần những nhóm chất nào? → chất bột đường, đạm, béo, vitamin và khoáng chất']::text[]),
  ('l8_sinh_bai_33_mau_va_he_tuan_hoan_cua_co_the_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 4, 'Bài 33: Máu và hệ tuần hoàn của cơ thể người', 'Máu gồm huyết tương, hồng cầu, bạch cầu, tiểu cầu; nhóm máu ABO và truyền máu; tim và hai vòng tuần hoàn; miễn dịch, vaccine; phòng bệnh tim mạch.', array['Hồng cầu làm nhiệm vụ gì? → vận chuyển O₂ và CO₂', 'Nhóm máu O truyền được cho nhóm nào? → cho được mọi nhóm (chỉ nhận nhóm O)']::text[]),
  ('l8_sinh_bai_34_he_ho_hap_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 5, 'Bài 34: Hệ hô hấp ở người', 'Đường dẫn khí và phổi; trao đổi khí ở phổi và ở tế bào; các bệnh hô hấp; tác hại của thuốc lá; hô hấp nhân tạo.', array['Trao đổi khí trong phổi xảy ra ở đâu? → phế nang', 'Vì sao không nên hút thuốc lá?']::text[]),
  ('l8_sinh_bai_35_he_bai_tiet_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 6, 'Bài 35: Hệ bài tiết ở người', 'Thận, ống dẫn nước tiểu, bóng đái, ống đái; thận lọc máu tạo nước tiểu; sỏi thận, suy thận; chạy thận nhân tạo, ghép thận; thói quen bảo vệ thận.', array['Cơ quan nào lọc máu tạo thành nước tiểu? → thận', 'Uống đủ nước giúp gì cho thận? → lọc máu tốt, tránh sỏi thận']::text[]),
  ('l8_sinh_bai_36_dieu_hoa_moi_truong_trong_cua_co_the_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 7, 'Bài 36: Điều hòa môi trường trong của cơ thể người', 'Môi trường trong gồm máu, nước mô, bạch huyết; cơ thể giữ cân bằng nội môi (đường huyết, pH, nhiệt độ…); ý nghĩa của các chỉ số xét nghiệm máu.', array['Môi trường trong cơ thể gồm những gì? → máu, nước mô, bạch huyết']::text[]),
  ('l8_sinh_bai_37_he_than_kinh_va_cac_giac_quan_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 8, 'Bài 37: Hệ thần kinh và các giác quan ở người', 'Não, tủy sống, dây thần kinh và chức năng; mắt (cận thị, viễn thị) và tai; cách bảo vệ mắt, tai; tác hại của chất gây nghiện với hệ thần kinh.', array['Cận thị là gì và phòng tránh thế nào? → nhìn xa mờ; giữ khoảng cách đọc, đủ ánh sáng, hạn chế màn hình', 'Bộ phận nào điều khiển mọi hoạt động của cơ thể? → não bộ']::text[]),
  ('l8_sinh_bai_38_he_noi_tiet_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 9, 'Bài 38: Hệ nội tiết ở người', 'Các tuyến nội tiết (yên, giáp, tụy, trên thận, sinh dục) tiết hormone điều hòa cơ thể; bệnh bướu cổ, tiểu đường và cách phòng.', array['Tuyến tụy tiết hormone gì để điều hòa đường huyết? → insulin', 'Thiếu iodine gây bệnh gì? → bướu cổ']::text[]),
  ('l8_sinh_bai_39_da_va_dieu_hoa_than_nhiet_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 10, 'Bài 39: Da và điều hòa thân nhiệt ở người', 'Cấu tạo da (biểu bì, bì, lớp mỡ dưới da); chức năng bảo vệ, cảm giác, bài tiết, điều hòa thân nhiệt (toát mồ hôi, co giãn mạch máu); chăm sóc da; cảm nóng, cảm lạnh.', array['Khi trời nóng, cơ thể làm gì để hạ nhiệt? → toát mồ hôi, mạch máu dưới da giãn ra']::text[]),
  ('l8_sinh_bai_40_sinh_san_o_nguoi', 'm_sinh', 8, 2, 'Chương 7: Sinh học cơ thể người', 11, 'Bài 40: Sinh sản ở người', 'Cơ quan sinh dục nam và nữ; thụ tinh, thụ thai; hiện tượng kinh nguyệt; bảo vệ sức khỏe sinh sản tuổi dậy thì; phòng tránh thai và bệnh lây qua đường tình dục.', array['Tuổi dậy thì có những thay đổi gì về cơ thể? Con giữ vệ sinh cơ thể thế nào?']::text[]),
  ('l8_sinh_bai_41_moi_truong_va_cac_nhan_to_sinh_thai', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 12, 'Bài 41: Môi trường và các nhân tố sinh thái', 'Bốn loại môi trường sống (nước, đất, trên cạn, sinh vật); nhân tố vô sinh và hữu sinh; giới hạn sinh thái của sinh vật.', array['Ánh sáng, nhiệt độ là nhân tố sinh thái loại gì? → vô sinh', 'Giun đất sống trong môi trường nào? → trong đất']::text[]),
  ('l8_sinh_bai_42_quan_the_sinh_vat', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 13, 'Bài 42: Quần thể sinh vật', 'Quần thể là tập hợp cá thể cùng loài, cùng sống trong một khu vực; các đặc trưng: kích thước, mật độ, tỉ lệ giới tính, nhóm tuổi, kiểu phân bố; bảo vệ quần thể.', array['Đàn cá chép trong một ao có phải là quần thể không? → có']::text[]),
  ('l8_sinh_bai_43_quan_xa_sinh_vat', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 14, 'Bài 43: Quần xã sinh vật', 'Quần xã gồm nhiều quần thể khác loài cùng sống trong một khu vực; đặc trưng: độ đa dạng, loài ưu thế, loài đặc trưng; bảo vệ đa dạng sinh học.', array['Quần xã khác quần thể ở điểm nào? → gồm nhiều loài']::text[]),
  ('l8_sinh_bai_44_he_sinh_thai', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 15, 'Bài 44: Hệ sinh thái', 'Hệ sinh thái = quần xã + môi trường; thành phần sinh vật sản xuất, tiêu thụ, phân giải; chuỗi và lưới thức ăn; các kiểu hệ sinh thái; bảo vệ hệ sinh thái.', array['Viết một chuỗi thức ăn ba mắt xích. → ví dụ: cỏ → thỏ → cáo', 'Sinh vật phân giải gồm những gì? → vi khuẩn, nấm']::text[]),
  ('l8_sinh_bai_45_sinh_quyen', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 16, 'Bài 45: Sinh quyển', 'Sinh quyển là toàn bộ sinh vật và môi trường sống của chúng trên Trái Đất; các khu sinh học (rừng, sa mạc, đồng cỏ, nước ngọt, biển).', array['Sinh quyển gồm những gì? → mọi sinh vật và nơi chúng sống trên Trái Đất']::text[]),
  ('l8_sinh_bai_46_can_bang_tu_nhien', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 17, 'Bài 46: Cân bằng tự nhiên', 'Trạng thái số lượng các loài ổn định nhờ điều hòa lẫn nhau; nguyên nhân mất cân bằng (phá rừng, săn bắt, ô nhiễm, sinh vật ngoại lai) và cách bảo vệ.', array['Việc làm nào của con người dễ gây mất cân bằng tự nhiên? → phá rừng, săn bắt quá mức, xả thải']::text[]),
  ('l8_sinh_bai_47_bao_ve_moi_truong', 'm_sinh', 8, 2, 'Chương 8: Sinh vật và môi trường', 18, 'Bài 47: Bảo vệ môi trường', 'Ô nhiễm môi trường, biến đổi khí hậu, suy giảm đa dạng sinh học; biện pháp: tiết kiệm năng lượng, trồng cây, giảm rác thải nhựa; phát triển bền vững.', array['Nhà mình có thể làm gì để giảm rác thải nhựa?']::text[]),
  ('l8_su_bai_1_cach_mang_tu_san_anh_va_chien_tranh_gianh_doc_lap_cua_13_thuoc_dia_anh_o_b', 'm_su', 8, 1, 'Chương 1: Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII', 1, 'Bài 1: Cách mạng tư sản Anh và chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ', 'Cách mạng tư sản Anh (1642–1688) lật đổ chế độ quân chủ chuyên chế, lập nền quân chủ lập hiến. 13 thuộc địa Anh ở Bắc Mỹ giành độc lập (1775–1783), công bố Tuyên ngôn Độc lập 4/7/1776, lập ra Hợp chúng quốc Hoa Kỳ.', array['Tuyên ngôn Độc lập của Mỹ công bố ngày nào? → 4/7/1776', 'Kết quả của Cách mạng tư sản Anh là gì? → lập chế độ quân chủ lập hiến']::text[]),
  ('l8_su_bai_2_cach_mang_tu_san_phap_cuoi_the_ki_xviii', 'm_su', 8, 1, 'Chương 1: Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII', 2, 'Bài 2: Cách mạng tư sản Pháp cuối thế kỉ XVIII', 'Nguyên nhân (mâu thuẫn ba đẳng cấp, khủng hoảng tài chính, tư tưởng Khai sáng); mở đầu 14/7/1789 phá ngục Ba-xti, phát triển qua các giai đoạn tới đỉnh cao chuyên chính Gia-cô-banh; ý nghĩa: lật đổ phong kiến, cuộc cách mạng tư sản triệt để nhất.', array['Ngày 14/7/1789 diễn ra sự kiện gì? → quần chúng phá ngục Ba-xti', 'Khẩu hiệu nổi tiếng của Cách mạng Pháp là gì? → Tự do – Bình đẳng – Bác ái']::text[]),
  ('l8_su_bai_3_cach_mang_cong_nghiep', 'm_su', 8, 1, 'Chương 1: Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII', 3, 'Bài 3: Cách mạng công nghiệp', 'Bắt đầu ở Anh nửa sau thế kỉ XVIII với máy kéo sợi Gien-ni, máy hơi nước của Giêm Oát, đầu máy xe lửa; lan sang Pháp, Đức, Mỹ. Tác động: sản xuất tăng vọt, đô thị hóa, hình thành giai cấp tư sản và vô sản, ô nhiễm môi trường.', array['Ai phát minh ra máy hơi nước? → Giêm Oát', 'Cách mạng công nghiệp bắt đầu ở nước nào? → Anh']::text[]),
  ('l8_su_bai_4_dong_nam_a_tu_nua_sau_the_ki_xvi_den_giua_the_ki_xix', 'm_su', 8, 1, 'Chương 2: Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX', 4, 'Bài 4: Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX', 'Các nước phương Tây (Bồ Đào Nha, Tây Ban Nha, Hà Lan, Anh, Pháp) xâm nhập rồi xâm lược Đông Nam Á; tình hình chính trị, kinh tế, văn hóa các nước; cuộc đấu tranh của nhân dân In-đô-nê-xi-a, Phi-líp-pin.', array['Nước nào chiếm Phi-líp-pin, nước nào chiếm In-đô-nê-xi-a? → Tây Ban Nha; Hà Lan']::text[]),
  ('l8_su_bai_5_cuoc_xung_dot_nam_bac_trieu_va_trinh_nguyen', 'm_su', 8, 1, 'Chương 3: Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII', 5, 'Bài 5: Cuộc xung đột Nam – Bắc triều và Trịnh – Nguyễn', 'Mạc Đăng Dung lập nhà Mạc (1527) dẫn tới xung đột Nam – Bắc triều (1533–1592); rồi Trịnh – Nguyễn phân tranh (1627–1672), đất nước chia cắt Đàng Ngoài – Đàng Trong lấy sông Gianh làm ranh giới; hậu quả với nhân dân.', array['Ranh giới Đàng Trong – Đàng Ngoài là sông nào? → sông Gianh', 'Ai lập ra nhà Mạc? → Mạc Đăng Dung']::text[]),
  ('l8_su_bai_6_cong_cuoc_khai_pha_vung_dat_phia_nam_tu_the_ki_xvi_den_the_ki_xviii', 'm_su', 8, 1, 'Chương 3: Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII', 6, 'Bài 6: Công cuộc khai phá vùng đất phía Nam từ thế kỉ XVI đến thế kỉ XVIII', 'Các chúa Nguyễn mở rộng lãnh thổ về phía Nam từ Phú Yên tới Hà Tiên, lập phủ Gia Định năm 1698 (Nguyễn Hữu Cảnh); khai phá và xác lập chủ quyền ở Hoàng Sa, Trường Sa qua đội Hoàng Sa, đội Bắc Hải.', array['Phủ Gia Định được lập năm nào, do ai? → 1698, Nguyễn Hữu Cảnh', 'Đội Hoàng Sa làm nhiệm vụ gì? → khai thác sản vật, thực thi chủ quyền ở Hoàng Sa, Trường Sa']::text[]),
  ('l8_su_bai_7_khoi_nghia_nong_dan_o_dang_ngoai_the_ki_xviii', 'm_su', 8, 1, 'Chương 3: Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII', 7, 'Bài 7: Khởi nghĩa nông dân ở Đàng Ngoài thế kỉ XVIII', 'Chính quyền Lê – Trịnh mục nát, nông dân cực khổ dẫn tới các cuộc khởi nghĩa của Nguyễn Hữu Cầu, Hoàng Công Chất, Nguyễn Danh Phương, Lê Duy Mật…; tuy thất bại nhưng làm lung lay chính quyền.', array['Kể tên hai cuộc khởi nghĩa nông dân ở Đàng Ngoài thế kỉ XVIII. → Nguyễn Hữu Cầu, Hoàng Công Chất…']::text[]),
  ('l8_su_bai_8_phong_trao_tay_son', 'm_su', 8, 1, 'Chương 3: Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII', 8, 'Bài 8: Phong trào Tây Sơn', 'Ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ khởi nghĩa năm 1771; lật đổ chúa Nguyễn, đánh tan quân Xiêm ở Rạch Gầm – Xoài Mút (1785), lật đổ Lê – Trịnh, đại phá quân Thanh ở Ngọc Hồi – Đống Đa (1789). Vai trò của Quang Trung.', array['Trận đánh quân Xiêm diễn ra ở đâu? → Rạch Gầm – Xoài Mút', 'Quang Trung đại phá quân Thanh năm nào? → 1789']::text[]),
  ('l8_su_bai_9_tinh_hinh_kinh_te_van_hoa_ton_giao_trong_cac_the_ki_xvi_xviii', 'm_su', 8, 1, 'Chương 3: Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII', 9, 'Bài 9: Tình hình kinh tế, văn hóa, tôn giáo trong các thế kỉ XVI – XVIII', 'Nông nghiệp Đàng Trong phát triển; thủ công nghiệp, thương nghiệp với các đô thị Thăng Long, Phố Hiến, Hội An; chữ Quốc ngữ ra đời, Thiên Chúa giáo du nhập; văn học chữ Nôm và nghệ thuật dân gian nở rộ.', array['Chữ Quốc ngữ ra đời vào thế kỉ nào, gắn với ai? → thế kỉ XVII, các giáo sĩ phương Tây như A-lếch-xăng đờ Rốt', 'Kể hai đô thị lớn của nước ta thời này. → Thăng Long, Phố Hiến, Hội An']::text[]),
  ('l8_su_bai_10_su_hinh_thanh_chu_nghia_de_quoc_o_cac_nuoc_au_my_cuoi_the_ki_xix_dau_the', 'm_su', 8, 1, 'Chương 4: Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX', 10, 'Bài 10: Sự hình thành chủ nghĩa đế quốc ở các nước Âu – Mỹ (cuối thế kỉ XIX – đầu thế kỉ XX)', 'Công ty độc quyền, tư bản tài chính, xuất khẩu tư bản và xâm chiếm thuộc địa đưa chủ nghĩa tư bản sang giai đoạn đế quốc; đặc điểm của Anh, Pháp, Đức, Mỹ.', array['Đặc điểm nổi bật của chủ nghĩa đế quốc là gì? → độc quyền, xâm chiếm thuộc địa']::text[]),
  ('l8_su_bai_11_phong_trao_cong_nhan_tu_cuoi_the_ki_xviii_den_dau_the_ki_xx_va_su_ra_doi', 'm_su', 8, 1, 'Chương 4: Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX', 11, 'Bài 11: Phong trào công nhân từ cuối thế kỉ XVIII đến đầu thế kỉ XX và sự ra đời của chủ nghĩa xã hội khoa học', 'Công nhân đấu tranh từ đập phá máy móc đến bãi công, đấu tranh chính trị; C. Mác và Ph. Ăng-ghen với "Tuyên ngôn của Đảng Cộng sản" (1848); Quốc tế thứ nhất, Công xã Pa-ri (1871), Quốc tế thứ hai.', array['"Tuyên ngôn của Đảng Cộng sản" ra đời năm nào? → 1848', 'Công xã Pa-ri thành lập năm nào? → 1871']::text[]),
  ('l8_su_bai_12_chien_tranh_the_gioi_thu_nhat_1914_1918_va_cach_mang_thang_muoi_nga_nam_1', 'm_su', 8, 1, 'Chương 4: Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX', 12, 'Bài 12: Chiến tranh thế giới thứ nhất (1914 – 1918) và Cách mạng tháng Mười Nga năm 1917', 'Nguyên nhân từ mâu thuẫn đế quốc về thuộc địa, hai khối Liên minh – Hiệp ước; diễn biến và hậu quả nặng nề. Cách mạng tháng Mười Nga do Lê-nin lãnh đạo lập ra nhà nước Xô viết.', array['Chiến tranh thế giới thứ nhất kéo dài từ năm nào đến năm nào? → 1914–1918', 'Ai lãnh đạo Cách mạng tháng Mười Nga? → Lê-nin']::text[]),
  ('l8_su_bai_13_su_phat_trien_cua_khoa_hoc_ki_thuat_van_hoc_nghe_thuat_trong_cac_the_ki_x', 'm_su', 8, 1, 'Chương 5: Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX', 13, 'Bài 13: Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX', 'Thành tựu khoa học (Niu-tơn, Đác-uyn với thuyết tiến hóa, Men-đê-lê-ép), kĩ thuật (luyện kim, điện, ô tô, máy bay), văn học (Ban-dắc, Vích-to Huy-gô, Lép Tôn-xtôi), âm nhạc (Mô-da, Bét-tô-ven) và hội họa.', array['Ai nêu ra thuyết tiến hóa? → Đác-uyn', 'Kể tên một nhà văn lớn thế kỉ XIX. → Vích-to Huy-gô, Ban-dắc, Lép Tôn-xtôi…']::text[]),
  ('l8_su_bai_14_trung_quoc_va_nhat_ban_tu_nua_sau_the_ki_xix_den_dau_the_ki_xx', 'm_su', 8, 2, 'Chương 6: Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX', 14, 'Bài 14: Trung Quốc và Nhật Bản từ nửa sau thế kỉ XIX đến đầu thế kỉ XX', 'Trung Quốc bị các nước đế quốc xâu xé; phong trào Thái bình Thiên quốc, Duy tân Mậu Tuất và Cách mạng Tân Hợi 1911 (Tôn Trung Sơn). Nhật Bản cải cách Duy tân Minh Trị (1868) trở thành nước đế quốc.', array['Cách mạng Tân Hợi nổ ra năm nào, ai lãnh đạo? → 1911, Tôn Trung Sơn', 'Cuộc Duy tân Minh Trị bắt đầu năm nào? → 1868']::text[]),
  ('l8_su_bai_15_an_do_va_dong_nam_a_tu_nua_sau_the_ki_xix_den_dau_the_ki_xx', 'm_su', 8, 2, 'Chương 6: Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX', 15, 'Bài 15: Ấn Độ và Đông Nam Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX', 'Thực dân Anh cai trị Ấn Độ, khởi nghĩa Xi-pay, Đảng Quốc đại; các nước Đông Nam Á lần lượt thành thuộc địa (trừ Xiêm) và phong trào chống thực dân.', array['Nước Đông Nam Á nào giữ được độc lập tương đối? → Xiêm (Thái Lan)']::text[]),
  ('l8_su_bai_16_viet_nam_duoi_thoi_nguyen_nua_dau_the_ki_xix', 'm_su', 8, 2, 'Chương 7: Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX', 16, 'Bài 16: Việt Nam dưới thời Nguyễn (nửa đầu thế kỉ XIX)', 'Nguyễn Ánh lập nhà Nguyễn năm 1802; bộ máy tập quyền, luật Gia Long, chia tỉnh thời Minh Mạng; kinh tế, xã hội và các cuộc khởi nghĩa nông dân; văn hóa với Truyện Kiều, quốc sử; thực thi chủ quyền ở Hoàng Sa, Trường Sa.', array['Nhà Nguyễn thành lập năm nào, vua đầu tiên là ai? → 1802, Gia Long', 'Vua nào chia cả nước thành 30 tỉnh và 1 phủ? → Minh Mạng']::text[]),
  ('l8_su_bai_17_cuoc_khang_chien_chong_thuc_dan_phap_xam_luoc_tu_nam_1858_den_nam_1884', 'm_su', 8, 2, 'Chương 7: Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX', 17, 'Bài 17: Cuộc kháng chiến chống thực dân Pháp xâm lược từ năm 1858 đến năm 1884', 'Pháp nổ súng ở Đà Nẵng (1/9/1858), chiếm Gia Định, ba tỉnh miền Đông rồi miền Tây Nam Kì, đánh ra Bắc Kì; các hiệp ước 1862, 1874, 1883, 1884 (Pa-tơ-nốt). Nhân dân kháng chiến với Trương Định, Nguyễn Trung Trực, Hoàng Diệu.', array['Pháp bắt đầu xâm lược nước ta ở đâu, năm nào? → Đà Nẵng, 1858', 'Hiệp ước nào đánh dấu Việt Nam mất hoàn toàn độc lập? → Hiệp ước Pa-tơ-nốt 1884']::text[]),
  ('l8_su_bai_18_phong_trao_chong_phap_trong_nhung_nam_1885_1896', 'm_su', 8, 2, 'Chương 7: Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX', 18, 'Bài 18: Phong trào chống Pháp trong những năm 1885 – 1896', 'Phong trào Cần vương từ chiếu Cần vương 1885 (Tôn Thất Thuyết, vua Hàm Nghi) với các khởi nghĩa Ba Đình, Bãi Sậy, Hương Khê (Phan Đình Phùng); khởi nghĩa nông dân Yên Thế của Hoàng Hoa Thám.', array['Ai ban chiếu Cần vương? → vua Hàm Nghi', 'Khởi nghĩa Yên Thế do ai lãnh đạo? → Hoàng Hoa Thám']::text[]),
  ('l8_su_bai_19_phong_trao_yeu_nuoc_chong_phap_o_viet_nam_tu_dau_the_ki_xx_den_nam_1917', 'm_su', 8, 2, 'Chương 7: Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX', 19, 'Bài 19: Phong trào yêu nước chống Pháp ở Việt Nam từ đầu thế kỉ XX đến năm 1917', 'Pháp khai thác thuộc địa lần thứ nhất làm xã hội chuyển biến; Phan Bội Châu với phong trào Đông du (bạo động), Phan Châu Trinh với Duy tân (cải cách), Đông Kinh nghĩa thục; Nguyễn Tất Thành ra đi tìm đường cứu nước 5/6/1911.', array['Phong trào Đông du do ai khởi xướng? → Phan Bội Châu', 'Nguyễn Tất Thành ra đi tìm đường cứu nước ngày nào? → 5/6/1911']::text[]),
  ('l8_su_chu_de_chung_1_van_minh_chau_tho_song_hong_va_song_cuu_long', 'm_su', 8, 2, 'Chủ đề chung Lịch sử và Địa lí', 20, 'Chủ đề chung 1: Văn minh châu thổ sông Hồng và sông Cửu Long', 'Quá trình hình thành hai châu thổ; chế độ nước và hệ thống đê điều sông Hồng, sống chung với lũ ở Cửu Long; văn minh lúa nước và đời sống cư dân hai vùng.', array['Vì sao sông Hồng có hệ thống đê còn sông Cửu Long thì không? → lũ sông Hồng lên nhanh, dữ; lũ Cửu Long lên chậm, hiền hòa và có lợi']::text[]),
  ('l8_su_chu_de_chung_2_bao_ve_chu_quyen_cac_quyen_va_loi_ich_hop_phap_cua_viet_nam_o_bie', 'm_su', 8, 2, 'Chủ đề chung Lịch sử và Địa lí', 21, 'Chủ đề chung 2: Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông', 'Phạm vi Biển Đông, các vùng biển theo Công ước Luật Biển 1982; bằng chứng lịch sử về chủ quyền Hoàng Sa, Trường Sa; trách nhiệm của công dân, học sinh.', array['Hai quần đảo lớn của Việt Nam ở Biển Đông là gì? → Hoàng Sa và Trường Sa']::text[]),
  ('l8_dia_bai_1_vi_tri_dia_li_va_pham_vi_lanh_tho_viet_nam', 'm_dia', 8, 1, 'Chương 1: Vị trí địa lí và phạm vi lãnh thổ, địa hình và khoáng sản Việt Nam', 1, 'Bài 1: Vị trí địa lí và phạm vi lãnh thổ Việt Nam', 'Nước ta nằm ở rìa đông bán đảo Đông Dương, trong vùng nội chí tuyến; lãnh thổ gồm đất liền (khoảng 331 nghìn km²), vùng biển rộng (khoảng 1 triệu km²) và vùng trời; các điểm cực. Vị trí quy định khí hậu nhiệt đới ẩm gió mùa.', array['Việt Nam nằm ở khu vực nào của châu Á? → Đông Nam Á', 'Diện tích đất liền nước ta khoảng bao nhiêu? → khoảng 331 nghìn km²']::text[]),
  ('l8_dia_bai_2_dia_hinh_viet_nam', 'm_dia', 8, 1, 'Chương 1: Vị trí địa lí và phạm vi lãnh thổ, địa hình và khoáng sản Việt Nam', 2, 'Bài 2: Địa hình Việt Nam', 'Đồi núi chiếm 3/4 diện tích, chủ yếu núi thấp; hướng tây bắc – đông nam và vòng cung; địa hình chịu tác động của con người. Các khu vực: Đông Bắc, Tây Bắc, Trường Sơn Bắc, Trường Sơn Nam, đồng bằng sông Hồng, sông Cửu Long, bờ biển và thềm lục địa.', array['Đồi núi chiếm bao nhiêu phần diện tích nước ta? → 3/4', 'Đỉnh núi cao nhất Việt Nam là gì? → Phan-xi-păng, 3147 m']::text[]),
  ('l8_dia_bai_3_khoang_san_viet_nam', 'm_dia', 8, 1, 'Chương 1: Vị trí địa lí và phạm vi lãnh thổ, địa hình và khoáng sản Việt Nam', 3, 'Bài 3: Khoáng sản Việt Nam', 'Khoáng sản đa dạng nhưng phần lớn trữ lượng vừa và nhỏ: than ở Quảng Ninh, dầu khí ở thềm lục địa phía Nam, bô-xít ở Tây Nguyên, apatit ở Lào Cai…; khai thác và sử dụng hợp lí.', array['Than đá tập trung nhiều nhất ở tỉnh nào? → Quảng Ninh', 'Dầu mỏ được khai thác chủ yếu ở đâu? → thềm lục địa phía Nam']::text[]),
  ('l8_dia_bai_4_khi_hau_viet_nam', 'm_dia', 8, 1, 'Chương 2: Khí hậu và thủy văn Việt Nam', 4, 'Bài 4: Khí hậu Việt Nam', 'Khí hậu nhiệt đới ẩm gió mùa: nhiệt độ cao, mưa nhiều; gió mùa đông (lạnh, khô ở miền Bắc) và gió mùa hạ (nóng ẩm, mưa nhiều); phân hóa theo Bắc – Nam, theo độ cao và Đông – Tây.', array['Miền Bắc có mùa đông lạnh là do gió gì? → gió mùa Đông Bắc', 'Khí hậu nước ta thuộc kiểu gì? → nhiệt đới ẩm gió mùa']::text[]),
  ('l8_dia_bai_5_thuc_hanh_ve_va_phan_tich_bieu_do_khi_hau', 'm_dia', 8, 1, 'Chương 2: Khí hậu và thủy văn Việt Nam', 5, 'Bài 5: Thực hành: vẽ và phân tích biểu đồ khí hậu', 'Vẽ biểu đồ nhiệt độ và lượng mưa của một trạm khí tượng rồi nhận xét mùa mưa, mùa khô, biên độ nhiệt.', array['Tháng nào ở trạm con vẽ có lượng mưa lớn nhất?']::text[]),
  ('l8_dia_bai_6_thuy_van_viet_nam', 'm_dia', 8, 1, 'Chương 2: Khí hậu và thủy văn Việt Nam', 6, 'Bài 6: Thủy văn Việt Nam', 'Mạng lưới sông ngòi dày đặc (2360 sông dài trên 10 km), chảy theo hướng tây bắc – đông nam và vòng cung, chế độ nước theo mùa; các hệ thống sông Hồng, Cửu Long, Đồng Nai; hồ, đầm và nước ngầm.', array['Hai hệ thống sông lớn nhất nước ta là gì? → sông Hồng và sông Cửu Long (Mê Công)', 'Mùa lũ của sông trùng với mùa gì? → mùa mưa']::text[]),
  ('l8_dia_bai_7_vai_tro_cua_tai_nguyen_khi_hau_va_tai_nguyen_nuoc_doi_voi_su_phat_trien_ki', 'm_dia', 8, 1, 'Chương 2: Khí hậu và thủy văn Việt Nam', 7, 'Bài 7: Vai trò của tài nguyên khí hậu và tài nguyên nước đối với sự phát triển kinh tế – xã hội của nước ta', 'Khí hậu thuận lợi cho nông nghiệp nhiệt đới, du lịch; nguồn nước phục vụ thủy điện, tưới tiêu, giao thông, sinh hoạt; thách thức từ thiên tai và ô nhiễm.', array['Khí hậu giúp gì cho nông nghiệp nước ta? → trồng nhiều vụ trong năm, nhiều cây nhiệt đới']::text[]),
  ('l8_dia_bai_8_tac_dong_cua_bien_doi_khi_hau_doi_voi_khi_hau_va_thuy_van_viet_nam', 'm_dia', 8, 1, 'Chương 2: Khí hậu và thủy văn Việt Nam', 8, 'Bài 8: Tác động của biến đổi khí hậu đối với khí hậu và thủy văn Việt Nam', 'Nhiệt độ tăng, mưa thất thường, bão mạnh hơn, nước biển dâng, hạn hán và lũ lụt cực đoan; giải pháp thích ứng và giảm nhẹ.', array['Nước biển dâng ảnh hưởng nặng nhất tới vùng nào? → đồng bằng sông Cửu Long', 'Gia đình mình có thể làm gì để giảm phát thải khí nhà kính?']::text[]),
  ('l8_dia_bai_9_tho_nhuong_viet_nam', 'm_dia', 8, 2, 'Chương 3: Thổ nhưỡng và sinh vật Việt Nam', 9, 'Bài 9: Thổ nhưỡng Việt Nam', 'Ba nhóm đất chính: đất feralit ở đồi núi (khoảng 65%), đất phù sa ở đồng bằng (khoảng 24%), đất mùn núi cao; đặc điểm, phân bố, giá trị sử dụng; thoái hóa đất và cách bảo vệ.', array['Nhóm đất nào chiếm diện tích lớn nhất? → đất feralit', 'Đất phù sa thích hợp trồng gì? → lúa, hoa màu, cây ăn quả']::text[]),
  ('l8_dia_bai_10_sinh_vat_viet_nam', 'm_dia', 8, 2, 'Chương 3: Thổ nhưỡng và sinh vật Việt Nam', 10, 'Bài 10: Sinh vật Việt Nam', 'Đa dạng sinh học cao về loài, gen và hệ sinh thái (rừng nhiệt đới, rừng ngập mặn…); suy giảm do khai thác quá mức; bảo tồn qua vườn quốc gia, khu bảo tồn.', array['Kể tên hai vườn quốc gia của Việt Nam. → Cúc Phương, Cát Tiên, Phong Nha – Kẻ Bàng…', 'Vì sao đa dạng sinh học bị suy giảm? → phá rừng, săn bắt, ô nhiễm, biến đổi khí hậu']::text[]),
  ('l8_dia_bai_11_pham_vi_bien_dong_vung_bien_dao_va_dac_diem_tu_nhien_vung_bien_dao_viet_n', 'm_dia', 8, 2, 'Chương 4: Biển đảo Việt Nam', 11, 'Bài 11: Phạm vi Biển Đông. Vùng biển đảo và đặc điểm tự nhiên vùng biển đảo Việt Nam', 'Biển Đông rộng khoảng 3,5 triệu km²; các vùng biển của nước ta (nội thủy, lãnh hải, tiếp giáp lãnh hải, đặc quyền kinh tế, thềm lục địa); đảo và quần đảo; đặc điểm khí hậu, hải văn, tài nguyên.', array['Lãnh hải rộng bao nhiêu hải lí? → 12 hải lí', 'Vùng đặc quyền kinh tế rộng bao nhiêu hải lí tính từ đường cơ sở? → 200 hải lí']::text[]),
  ('l8_dia_bai_12_moi_truong_va_tai_nguyen_thien_nhien_bien_dao_viet_nam', 'm_dia', 8, 2, 'Chương 4: Biển đảo Việt Nam', 12, 'Bài 12: Môi trường và tài nguyên thiên nhiên biển đảo Việt Nam', 'Tài nguyên sinh vật, khoáng sản (dầu khí, cát, muối), du lịch, giao thông biển; ô nhiễm biển và suy giảm tài nguyên; bảo vệ môi trường biển đảo.', array['Kể ba loại tài nguyên biển. → hải sản, dầu khí, muối, du lịch…', 'Con có thể làm gì để bảo vệ biển?']::text[]),
  ('l8_gdcd_bai_1_tu_hao_ve_truyen_thong_dan_toc_viet_nam', 'm_gdcd', 8, 1, 'Giáo dục công dân 8 — Học kì I', 1, 'Bài 1: Tự hào về truyền thống dân tộc Việt Nam', 'Các truyền thống yêu nước, đoàn kết, nhân nghĩa, hiếu học, cần cù…; giá trị của truyền thống; biểu hiện của lòng tự hào và phê phán hành vi xúc phạm truyền thống.', array['Kể ba truyền thống tốt đẹp của dân tộc ta.', 'Con thể hiện lòng tự hào dân tộc bằng việc làm gì?']::text[]),
  ('l8_gdcd_bai_2_ton_trong_su_da_dang_cua_cac_dan_toc', 'm_gdcd', 8, 1, 'Giáo dục công dân 8 — Học kì I', 2, 'Bài 2: Tôn trọng sự đa dạng của các dân tộc', 'Mỗi dân tộc có nền văn hóa riêng đáng trân trọng; tôn trọng, học hỏi lẫn nhau; không kì thị, phân biệt đối xử.', array['Vì sao cần tôn trọng sự đa dạng văn hóa của các dân tộc?']::text[]),
  ('l8_gdcd_bai_3_lao_dong_can_cu_sang_tao', 'm_gdcd', 8, 1, 'Giáo dục công dân 8 — Học kì I', 3, 'Bài 3: Lao động cần cù, sáng tạo', 'Cần cù là chăm chỉ, kiên trì; sáng tạo là tìm cách làm mới, hiệu quả hơn; ý nghĩa và cách rèn luyện trong học tập, lao động.', array['Tuần này con đã làm việc gì một cách sáng tạo?']::text[]),
  ('l8_gdcd_bai_4_bao_ve_le_phai', 'm_gdcd', 8, 1, 'Giáo dục công dân 8 — Học kì I', 4, 'Bài 4: Bảo vệ lẽ phải', 'Lẽ phải là điều đúng đắn, phù hợp đạo lí và lợi ích chung; bảo vệ lẽ phải bằng lời nói, việc làm; dũng cảm, không a dua theo số đông.', array['Thấy bạn bị bắt nạt, con sẽ làm gì?']::text[]),
  ('l8_gdcd_bai_5_bao_ve_moi_truong_va_tai_nguyen_thien_nhien', 'm_gdcd', 8, 1, 'Giáo dục công dân 8 — Học kì I', 5, 'Bài 5: Bảo vệ môi trường và tài nguyên thiên nhiên', 'Sự cần thiết của việc bảo vệ; một số quy định pháp luật; trách nhiệm của học sinh: tiết kiệm, không xả rác, tố giác hành vi vi phạm.', array['Kể ba việc con làm để bảo vệ môi trường.']::text[]),
  ('l8_gdcd_bai_6_xac_dinh_muc_tieu_ca_nhan', 'm_gdcd', 8, 2, 'Giáo dục công dân 8 — Học kì II', 6, 'Bài 6: Xác định mục tiêu cá nhân', 'Mục tiêu ngắn hạn và dài hạn; đặt mục tiêu theo tiêu chí cụ thể, đo được, khả thi, thực tế, có thời hạn; lập kế hoạch thực hiện.', array['Mục tiêu học kì này của con là gì? Đo bằng gì?']::text[]),
  ('l8_gdcd_bai_7_phong_chong_bao_luc_gia_dinh', 'm_gdcd', 8, 2, 'Giáo dục công dân 8 — Học kì II', 7, 'Bài 7: Phòng, chống bạo lực gia đình', 'Các hình thức bạo lực gia đình (thể chất, tinh thần, kinh tế, tình dục), tác hại; quy định của pháp luật; cách ứng phó và tìm sự giúp đỡ.', array['Khi bị bạo lực gia đình có thể gọi số nào để được giúp? → 111 (trẻ em) hoặc 113 (công an)']::text[]),
  ('l8_gdcd_bai_8_lap_ke_hoach_chi_tieu', 'm_gdcd', 8, 2, 'Giáo dục công dân 8 — Học kì II', 8, 'Bài 8: Lập kế hoạch chi tiêu', 'Xác định thu nhập, phân biệt khoản chi cần thiết và không cần thiết, dành phần tiết kiệm; ghi chép và điều chỉnh kế hoạch.', array['Tiền tiêu vặt tháng này con chi vào những gì? Tiết kiệm được bao nhiêu?']::text[]),
  ('l8_gdcd_bai_9_phong_ngua_tai_nan_vu_khi_chay_no_va_cac_chat_doc_hai', 'm_gdcd', 8, 2, 'Giáo dục công dân 8 — Học kì II', 9, 'Bài 9: Phòng ngừa tai nạn vũ khí, cháy, nổ và các chất độc hại', 'Nguy cơ và hậu quả của tai nạn cháy nổ, hóa chất; quy định pháp luật; kĩ năng phòng ngừa: không đốt pháo, kiểm tra điện, gas, cất hóa chất đúng chỗ.', array['Nhà mình để bình gas, ổ điện đã an toàn chưa? Có cháy thì gọi số nào? → 114']::text[]),
  ('l8_gdcd_bai_10_quyen_va_nghia_vu_lao_dong_cua_cong_dan', 'm_gdcd', 8, 2, 'Giáo dục công dân 8 — Học kì II', 10, 'Bài 10: Quyền và nghĩa vụ lao động của công dân', 'Lao động vừa là quyền vừa là nghĩa vụ; quy định về lao động chưa thành niên (không làm việc nặng nhọc, độc hại; giới hạn giờ làm); hợp đồng lao động.', array['Người dưới 15 tuổi có được làm việc nặng nhọc, độc hại không? → không']::text[]),
  ('l8_tin_bai_1_luoc_su_cong_cu_tinh_toan', 'm_tin', 8, 1, 'Chủ đề 1: Máy tính và cộng đồng', 1, 'Bài 1: Lược sử công cụ tính toán', 'Từ bàn tính, máy tính cơ khí đến máy tính điện tử qua các thế hệ (đèn điện tử, bán dẫn, vi mạch, vi xử lí) và máy tính hiện đại; các nhân vật như Charles Babbage, Alan Turing, John von Neumann.', array['Máy tính điện tử đầu tiên tên là gì? → ENIAC', 'Kể các thế hệ máy tính đã học.']::text[]),
  ('l8_tin_bai_2_thong_tin_trong_moi_truong_so', 'm_tin', 8, 1, 'Chủ đề 2: Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin', 2, 'Bài 2: Thông tin trong môi trường số', 'Đặc điểm thông tin số: đa dạng, dễ nhân bản, lan truyền nhanh, khó thu hồi; đánh giá độ tin cậy của thông tin và nguồn tin đáng tin cậy.', array['Dấu hiệu nào cho thấy một tin trên mạng đáng tin cậy? → nguồn rõ ràng, tác giả uy tín, có kiểm chứng']::text[]),
  ('l8_tin_bai_3_thuc_hanh_khai_thac_thong_tin_so', 'm_tin', 8, 1, 'Chủ đề 2: Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin', 3, 'Bài 3: Thực hành: Khai thác thông tin số', 'Tìm kiếm, đánh giá, chọn lọc thông tin trên Internet cho một chủ đề và ghi rõ nguồn.', array['Con tìm thông tin cho chủ đề gì? Lấy từ nguồn nào?']::text[]),
  ('l8_tin_bai_4_dao_duc_va_van_hoa_trong_su_dung_cong_nghe_ki_thuat_so', 'm_tin', 8, 1, 'Chủ đề 3: Đạo đức, pháp luật và văn hóa trong môi trường số', 4, 'Bài 4: Đạo đức và văn hóa trong sử dụng công nghệ kĩ thuật số', 'Các biểu hiện vi phạm (bắt nạt trên mạng, đăng ảnh người khác không xin phép, vi phạm bản quyền, lan truyền tin giả); ứng xử có văn hóa và tôn trọng pháp luật trên không gian số.', array['Đăng ảnh bạn lên mạng mà không hỏi ý kiến có được không? → không']::text[]),
  ('l8_tin_bai_5_su_dung_bang_tinh_giai_quyet_bai_toan_thuc_te', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 5, 'Bài 5: Sử dụng bảng tính giải quyết bài toán thực tế', 'Địa chỉ tương đối và tuyệt đối ($A$1), sao chép công thức, các hàm cơ bản SUM, AVERAGE, MAX, MIN, COUNT trong bảng tính.', array['Địa chỉ $A$1 khác A1 ở chỗ nào? → không đổi khi sao chép công thức', 'Hàm tính trung bình cộng là gì? → AVERAGE']::text[]),
  ('l8_tin_bai_6_sap_xep_va_loc_du_lieu', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 6, 'Bài 6: Sắp xếp và lọc dữ liệu', 'Sắp xếp tăng, giảm theo một hoặc nhiều cột; lọc dữ liệu theo điều kiện trong bảng tính.', array['Muốn chỉ xem học sinh điểm từ 8 trở lên dùng chức năng gì? → lọc (Filter)']::text[]),
  ('l8_tin_bai_7_trinh_bay_du_lieu_bang_bieu_do', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 7, 'Bài 7: Trình bày dữ liệu bằng biểu đồ', 'Chọn kiểu biểu đồ phù hợp (cột, đường, tròn), tạo và chỉnh sửa biểu đồ từ bảng tính.', array['Biểu đồ nào phù hợp để so sánh tỉ lệ phần trăm? → biểu đồ tròn']::text[]),
  ('l8_tin_bai_8a_lam_viec_voi_danh_sach_dang_liet_ke_va_hinh_anh_trong_van_ban', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 8, 'Bài 8a: Làm việc với danh sách dạng liệt kê và hình ảnh trong văn bản', 'Tạo danh sách gạch đầu dòng, đánh số; chèn và bố trí hình ảnh trong văn bản.', array['Con chèn hình vào văn bản và cho chữ bao quanh được chưa?']::text[]),
  ('l8_tin_bai_9a_tao_dau_trang_chan_trang_cho_van_ban', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 9, 'Bài 9a: Tạo đầu trang, chân trang cho văn bản', 'Tạo Header, Footer, đánh số trang tự động cho văn bản nhiều trang.', array['Đánh số trang tự động nằm ở đầu trang hay chân trang? → tùy chọn, thường ở chân trang']::text[]),
  ('l8_tin_bai_10a_dinh_dang_nang_cao_cho_trang_chieu', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 10, 'Bài 10a: Định dạng nâng cao cho trang chiếu', 'Bố cục trang chiếu, màu nền, hiệu ứng chuyển trang và hiệu ứng động cho đối tượng.', array['Con làm được hiệu ứng chuyển trang chưa?']::text[]),
  ('l8_tin_bai_11a_su_dung_ban_mau_tao_bai_trinh_chieu', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 11, 'Bài 11a: Sử dụng bản mẫu tạo bài trình chiếu', 'Dùng bản mẫu (template, theme) để tạo bài trình chiếu nhanh và nhất quán.', array['Bản mẫu giúp gì khi làm bài trình chiếu? → nhanh, đồng bộ về màu sắc, bố cục']::text[]),
  ('l8_tin_bai_8b_phan_mem_chinh_sua_anh', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 12, 'Bài 8b: Phần mềm chỉnh sửa ảnh', 'Làm quen phần mềm chỉnh sửa ảnh: mở, lưu, các công cụ cơ bản và vùng làm việc.', array['Con dùng phần mềm nào để chỉnh ảnh ở lớp?']::text[]),
  ('l8_tin_bai_9b_thay_doi_khung_hinh_kich_thuoc_anh', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 13, 'Bài 9b: Thay đổi khung hình, kích thước ảnh', 'Cắt (crop), xoay, thay đổi kích thước và độ phân giải ảnh.', array['Cắt ảnh khác thay đổi kích thước ở chỗ nào? → cắt bỏ bớt phần ảnh; đổi kích thước giữ nguyên nội dung']::text[]),
  ('l8_tin_bai_10b_them_van_ban_tao_hieu_ung_cho_anh', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 14, 'Bài 10b: Thêm văn bản, tạo hiệu ứng cho ảnh', 'Chèn chữ, dùng lớp (layer), bộ lọc và hiệu ứng cho ảnh.', array['Lớp (layer) trong phần mềm ảnh dùng để làm gì?']::text[]),
  ('l8_tin_bai_11b_thuc_hanh_tong_hop', 'm_tin', 8, 1, 'Chủ đề 4: Ứng dụng tin học', 15, 'Bài 11b: Thực hành tổng hợp', 'Làm một sản phẩm ảnh hoàn chỉnh (poster, thiệp) từ các kĩ năng đã học.', array['Con làm sản phẩm gì? Cho bố mẹ xem.']::text[]),
  ('l8_tin_bai_12_tu_thuat_toan_den_chuong_trinh', 'm_tin', 8, 2, 'Chủ đề 5: Giải quyết vấn đề với sự trợ giúp của máy tính', 16, 'Bài 12: Từ thuật toán đến chương trình', 'Thuật toán được thể hiện thành chương trình (Scratch); cấu trúc tuần tự; khái niệm biến, hằng và kiểu dữ liệu.', array['Thuật toán là gì? → dãy các bước rõ ràng để giải một bài toán']::text[]),
  ('l8_tin_bai_13_bieu_dien_du_lieu', 'm_tin', 8, 2, 'Chủ đề 5: Giải quyết vấn đề với sự trợ giúp của máy tính', 17, 'Bài 13: Biểu diễn dữ liệu', 'Kiểu dữ liệu số, xâu kí tự, lôgic; biến và hằng; biểu thức và phép toán trong chương trình.', array['Biến dùng để làm gì trong chương trình? → lưu giá trị có thể thay đổi']::text[]),
  ('l8_tin_bai_14_cau_truc_dieu_khien', 'm_tin', 8, 2, 'Chủ đề 5: Giải quyết vấn đề với sự trợ giúp của máy tính', 18, 'Bài 14: Cấu trúc điều khiển', 'Cấu trúc rẽ nhánh (nếu… thì…, nếu không…) và cấu trúc lặp (lặp n lần, lặp khi điều kiện còn đúng).', array['Muốn lặp một việc 10 lần dùng khối lệnh gì? → lặp lại 10 lần (repeat)']::text[]),
  ('l8_tin_bai_15_go_loi', 'm_tin', 8, 2, 'Chủ đề 5: Giải quyết vấn đề với sự trợ giúp của máy tính', 19, 'Bài 15: Gỡ lỗi', 'Lỗi cú pháp và lỗi lôgic; cách tìm lỗi: chạy từng bước, kiểm tra giá trị biến, thử với dữ liệu nhỏ.', array['Lỗi lôgic là gì? → chương trình chạy được nhưng cho kết quả sai']::text[]),
  ('l8_tin_bai_16_tin_hoc_voi_nghe_nghiep', 'm_tin', 8, 2, 'Chủ đề 6: Hướng nghiệp với tin học', 20, 'Bài 16: Tin học với nghề nghiệp', 'Các nhóm nghề trong lĩnh vực tin học (lập trình, thiết kế, quản trị mạng, phân tích dữ liệu…) và các nghề ứng dụng tin học; định hướng bản thân.', array['Con thích nghề nào có liên quan đến tin học? Vì sao?']::text[]),
  ('l8_cn_bai_1_mot_so_tieu_chuan_trinh_bay_ban_ve_ki_thuat', 'm_cn', 8, 1, 'Chương 1: Vẽ kĩ thuật', 1, 'Bài 1: Một số tiêu chuẩn trình bày bản vẽ kĩ thuật', 'Khổ giấy (A4, A3…), tỉ lệ, các loại nét vẽ (liền đậm, liền mảnh, đứt mảnh, gạch chấm mảnh), cách ghi kích thước và chữ viết trên bản vẽ.', array['Nét đứt mảnh dùng để vẽ gì? → đường bao khuất, cạnh khuất', 'Tỉ lệ 1:2 nghĩa là gì? → hình vẽ nhỏ bằng một nửa vật thật']::text[]),
  ('l8_cn_bai_2_hinh_chieu_vuong_goc', 'm_cn', 8, 1, 'Chương 1: Vẽ kĩ thuật', 2, 'Bài 2: Hình chiếu vuông góc', 'Phép chiếu vuông góc; ba hình chiếu đứng, bằng, cạnh và vị trí của chúng trên bản vẽ; hình chiếu của khối đa diện và khối tròn xoay.', array['Hình chiếu bằng nằm ở đâu so với hình chiếu đứng? → ở phía dưới', 'Hình trụ đặt đứng có hình chiếu bằng là hình gì? → hình tròn']::text[]),
  ('l8_cn_bai_3_ban_ve_chi_tiet', 'm_cn', 8, 1, 'Chương 1: Vẽ kĩ thuật', 3, 'Bài 3: Bản vẽ chi tiết', 'Nội dung bản vẽ chi tiết: hình biểu diễn, kích thước, yêu cầu kĩ thuật, khung tên; trình tự đọc bản vẽ.', array['Bản vẽ chi tiết gồm mấy nội dung chính? → 4']::text[]),
  ('l8_cn_bai_4_ban_ve_lap', 'm_cn', 8, 1, 'Chương 1: Vẽ kĩ thuật', 4, 'Bài 4: Bản vẽ lắp', 'Bản vẽ lắp diễn tả hình dạng, vị trí tương quan của các chi tiết trong một sản phẩm; bảng kê; trình tự đọc.', array['Bản vẽ lắp khác bản vẽ chi tiết ở chỗ nào? → thể hiện nhiều chi tiết ghép với nhau, có bảng kê']::text[]),
  ('l8_cn_bai_5_ban_ve_nha', 'm_cn', 8, 1, 'Chương 1: Vẽ kĩ thuật', 5, 'Bài 5: Bản vẽ nhà', 'Mặt bằng, mặt đứng, mặt cắt của ngôi nhà; kí hiệu cửa đi, cửa sổ, cầu thang; cách đọc bản vẽ nhà.', array['Mặt bằng cho biết gì về ngôi nhà? → vị trí, kích thước các phòng, cửa']::text[]),
  ('l8_cn_on_tap_chuong_1', 'm_cn', 8, 1, 'Chương 1: Vẽ kĩ thuật', 6, 'Ôn tập chương 1', 'Ôn tiêu chuẩn bản vẽ, hình chiếu, bản vẽ chi tiết, bản vẽ lắp, bản vẽ nhà.', array['Con thử đọc một bản vẽ nhà đơn giản cho bố mẹ nghe.']::text[]),
  ('l8_cn_bai_6_vat_lieu_co_khi', 'm_cn', 8, 1, 'Chương 2: Cơ khí', 7, 'Bài 6: Vật liệu cơ khí', 'Kim loại đen (gang, thép), kim loại màu (đồng, nhôm và hợp kim), phi kim loại (chất dẻo, cao su); tính chất và ứng dụng.', array['Gang và thép khác nhau ở điểm gì? → tỉ lệ carbon (gang nhiều carbon hơn)', 'Kể hai vật liệu phi kim loại dùng trong cơ khí. → chất dẻo, cao su']::text[]),
  ('l8_cn_bai_7_truyen_va_bien_doi_chuyen_dong', 'm_cn', 8, 1, 'Chương 2: Cơ khí', 8, 'Bài 7: Truyền và biến đổi chuyển động', 'Truyền động ma sát (đai) và ăn khớp (bánh răng, xích); tỉ số truyền i = n₂/n₁ = Z₁/Z₂; biến đổi chuyển động quay thành tịnh tiến (tay quay – con trượt) và quay thành lắc.', array['Xe đạp dùng bộ truyền động gì? → truyền động xích', 'Đĩa 40 răng, líp 20 răng thì tỉ số truyền bằng? → 2 (líp quay nhanh gấp đôi đĩa)']::text[]),
  ('l8_cn_bai_8_gia_cong_co_khi_bang_tay', 'm_cn', 8, 1, 'Chương 2: Cơ khí', 9, 'Bài 8: Gia công cơ khí bằng tay', 'Dụng cụ đo (thước lá, thước cặp), vạch dấu, cưa, dũa, đục, khoan; kĩ thuật thao tác và an toàn lao động.', array['Khi cưa kim loại cần chú ý an toàn gì? → kẹp chặt phôi, không dùng cưa lỏng, đeo bảo hộ']::text[]),
  ('l8_cn_bai_9_nganh_nghe_trong_linh_vuc_co_khi', 'm_cn', 8, 1, 'Chương 2: Cơ khí', 10, 'Bài 9: Ngành nghề trong lĩnh vực cơ khí', 'Kĩ sư cơ khí, kĩ thuật viên, thợ cơ khí…; đặc điểm công việc, yêu cầu và cơ hội nghề nghiệp.', array['Con kể một nghề trong lĩnh vực cơ khí và công việc của nghề đó.']::text[]),
  ('l8_cn_bai_10_du_an_gia_cong_chi_tiet_bang_dung_cu_cam_tay', 'm_cn', 8, 1, 'Chương 2: Cơ khí', 11, 'Bài 10: Dự án: Gia công chi tiết bằng dụng cụ cầm tay', 'Thiết kế, vạch dấu và gia công một chi tiết đơn giản (móc treo, ke góc…) bằng dụng cụ cầm tay.', array['Nhóm con làm sản phẩm gì? Khâu nào khó nhất?']::text[]),
  ('l8_cn_on_tap_chuong_2', 'm_cn', 8, 1, 'Chương 2: Cơ khí', 12, 'Ôn tập chương 2', 'Ôn vật liệu cơ khí, truyền và biến đổi chuyển động, gia công bằng tay, nghề cơ khí.', array['Con nhắc lại công thức tỉ số truyền.']::text[]),
  ('l8_cn_bai_11_tai_nan_dien', 'm_cn', 8, 2, 'Chương 3: An toàn điện', 13, 'Bài 11: Tai nạn điện', 'Nguyên nhân tai nạn điện: chạm vào vật mang điện, vi phạm khoảng cách an toàn với đường dây cao áp, đến gần dây điện đứt rơi xuống đất; hậu quả.', array['Kể ba nguyên nhân gây tai nạn điện.']::text[]),
  ('l8_cn_bai_12_bien_phap_an_toan_dien', 'm_cn', 8, 2, 'Chương 3: An toàn điện', 14, 'Bài 12: Biện pháp an toàn điện', 'Nguyên tắc an toàn: kiểm tra cách điện, dùng dụng cụ bảo vệ (găng, ủng cao su, bút thử điện), ngắt nguồn trước khi sửa chữa; aptomat, nối đất thiết bị.', array['Trước khi sửa đồ điện phải làm gì đầu tiên? → ngắt nguồn điện', 'Bút thử điện dùng để làm gì? → kiểm tra vật có điện hay không']::text[]),
  ('l8_cn_bai_13_so_cuu_nguoi_bi_tai_nan_dien', 'm_cn', 8, 2, 'Chương 3: An toàn điện', 15, 'Bài 13: Sơ cứu người bị tai nạn điện', 'Tách nạn nhân khỏi nguồn điện (ngắt điện, dùng vật cách điện), sơ cứu (hô hấp nhân tạo, ép tim ngoài lồng ngực) và gọi cấp cứu.', array['Thấy người bị điện giật, việc đầu tiên cần làm là gì? → ngắt nguồn điện, không chạm tay trần vào nạn nhân']::text[]),
  ('l8_cn_on_tap_chuong_3', 'm_cn', 8, 2, 'Chương 3: An toàn điện', 16, 'Ôn tập chương 3', 'Ôn nguyên nhân tai nạn điện, biện pháp an toàn và sơ cứu.', array['Số điện thoại cấp cứu y tế là gì? → 115']::text[]),
  ('l8_cn_bai_14_khai_quat_ve_mach_dien', 'm_cn', 8, 2, 'Chương 4: Kĩ thuật điện', 17, 'Bài 14: Khái quát về mạch điện', 'Thành phần mạch điện: nguồn điện, bộ phận truyền dẫn – đóng cắt – bảo vệ (dây dẫn, công tắc, cầu chì, aptomat), phụ tải; sơ đồ mạch điện.', array['Cầu chì và aptomat có nhiệm vụ gì? → bảo vệ mạch khi quá tải, ngắn mạch']::text[]),
  ('l8_cn_bai_15_cam_bien_va_mo_dun_cam_bien', 'm_cn', 8, 2, 'Chương 4: Kĩ thuật điện', 18, 'Bài 15: Cảm biến và mô đun cảm biến', 'Cảm biến ánh sáng, nhiệt độ, độ ẩm, hồng ngoại…; mô đun cảm biến biến tín hiệu thành lệnh đóng, cắt mạch.', array['Đèn đường tự bật khi trời tối dùng cảm biến gì? → cảm biến ánh sáng']::text[]),
  ('l8_cn_bai_16_mach_dien_dieu_khien_su_dung_mo_dun_cam_bien', 'm_cn', 8, 2, 'Chương 4: Kĩ thuật điện', 19, 'Bài 16: Mạch điện điều khiển sử dụng mô đun cảm biến', 'Lắp mạch nguồn – mô đun cảm biến – tải (đèn, quạt, máy bơm); ứng dụng bật đèn tự động, tưới cây tự động.', array['Mạch tưới cây tự động cần cảm biến gì? → cảm biến độ ẩm đất']::text[]),
  ('l8_cn_bai_17_nganh_nghe_trong_linh_vuc_ki_thuat_dien', 'm_cn', 8, 2, 'Chương 4: Kĩ thuật điện', 20, 'Bài 17: Ngành nghề trong lĩnh vực kĩ thuật điện', 'Kĩ sư điện, kĩ thuật viên điện, thợ điện…; công việc, yêu cầu và an toàn nghề nghiệp.', array['Con kể một nghề trong lĩnh vực kĩ thuật điện.']::text[]),
  ('l8_cn_on_tap_chuong_4', 'm_cn', 8, 2, 'Chương 4: Kĩ thuật điện', 21, 'Ôn tập chương 4', 'Ôn mạch điện, cảm biến, mạch điều khiển, nghề kĩ thuật điện.', array['Con vẽ sơ đồ một mạch điện có cảm biến.']::text[]),
  ('l8_cn_bai_18_gioi_thieu_ve_thiet_ke_ki_thuat', 'm_cn', 8, 2, 'Chương 5: Thiết kế kĩ thuật', 22, 'Bài 18: Giới thiệu về thiết kế kĩ thuật', 'Thiết kế kĩ thuật là gì, vai trò trong đời sống và sản xuất; các ngành nghề liên quan đến thiết kế.', array['Thiết kế kĩ thuật nhằm mục đích gì? → tạo ra sản phẩm giải quyết nhu cầu thực tế']::text[]),
  ('l8_cn_bai_19_cac_buoc_co_ban_trong_thiet_ke_ki_thuat', 'm_cn', 8, 2, 'Chương 5: Thiết kế kĩ thuật', 23, 'Bài 19: Các bước cơ bản trong thiết kế kĩ thuật', 'Quy trình: xác định vấn đề – tìm hiểu thông tin – đề xuất giải pháp – làm mẫu thử – đánh giá và hoàn thiện.', array['Kể năm bước thiết kế kĩ thuật.']::text[]),
  ('l8_cn_bai_20_du_an_thiet_ke_he_thong_tuoi_cay_tu_dong', 'm_cn', 8, 2, 'Chương 5: Thiết kế kĩ thuật', 24, 'Bài 20: Dự án: Thiết kế hệ thống tưới cây tự động', 'Áp dụng quy trình thiết kế với cảm biến độ ẩm, mô đun và máy bơm để tưới cây tự động.', array['Hệ thống của nhóm con hoạt động thế nào? Có gì cần cải tiến?']::text[]),
  ('l8_cn_on_tap_chuong_5', 'm_cn', 8, 2, 'Chương 5: Thiết kế kĩ thuật', 25, 'Ôn tập chương 5', 'Ôn quy trình thiết kế kĩ thuật.', array['Con nhắc lại các bước thiết kế và cho ví dụ.']::text[])
